// ---------- storage helpers ----------
async function loadLorries() {
  try {
    const res = await window.storage.get("lorries", true);
    return res ? JSON.parse(res.value) : [];
  } catch {
    return [];
  }
}
async function saveLorries(list) {
  try {
    const res = await window.storage.set("lorries", JSON.stringify(list), true);
    return !!res;
  } catch (e) {
    console.error("save lorries failed", e);
    return false;
  }
}
