// Resize/compress a photo file down to a small square thumbnail (base64
// data URL) before it's stored, so each user's photo stays a few KB rather
// than bloating the shared "users" document.
function resizePhotoFile(file, maxSize = 160, quality = 0.7) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        let { width, height } = img;
        if (width > height) {
          if (width > maxSize) { height = Math.round((height * maxSize) / width); width = maxSize; }
        } else {
          if (height > maxSize) { width = Math.round((width * maxSize) / height); height = maxSize; }
        }
        const canvas = document.createElement("canvas");
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL("image/jpeg", quality));
      };
      img.onerror = () => reject(new Error("Could not read image"));
      img.src = e.target.result;
    };
    reader.onerror = () => reject(new Error("Could not read file"));
    reader.readAsDataURL(file);
  });
}

function computePayment(lorry, hammaliRate) {
  // The farmer's final payment is designed to always land on a round
  // number by construction, rather than being rounded as a separate visible
  // step. In practice, a farmer doesn't mind the hammali (labour) deduction
  // varying by a rupee or two, but does mind seeing "your payment" itself
  // reduced by loose change — so any rounding adjustment (typically ±1 to
  // ₹5) is absorbed into the hammali line instead of ever touching the
  // final payable figure.
  const gross = lorry.weight * lorry.rate;
  const rawHammali = lorry.weight * hammaliRate;
  const rawNet = gross - rawHammali - WEIGHING_CHARGE;
  const rounded = Math.round(rawNet / 10) * 10; // this IS the final payment — always round, never shown as "rounded"
  const hammali = gross - WEIGHING_CHARGE - rounded; // back-solved so the numbers tie out exactly
  const deduction = hammali + WEIGHING_CHARGE;
  return { gross, hammali, weighingCharge: WEIGHING_CHARGE, deduction, net: rounded, rounded };
}

function heapStats(heapId, lorries) {
  const list = lorries.filter((l) => l.heapId === heapId);
  const totalWeight = list.reduce((s, l) => s + (l.weight || 0), 0);
  const ratedList = list.filter((l) => l.rate);
  const ratedWeight = ratedList.reduce((s, l) => s + l.weight, 0);
  const weightedRateSum = ratedList.reduce((s, l) => s + l.weight * l.rate, 0);
  const avgRate = ratedWeight > 0 ? weightedRateSum / ratedWeight : null;
  return { count: list.length, totalWeight, avgRate, lorries: list };
}

function baleStats(heapId, bales) {
  const list = bales.filter((b) => b.heapId === heapId).sort((a, b) => a.baleNumber - b.baleNumber);
  const totalWeight = list.reduce((s, b) => s + (b.weight || 0), 0);
  return { count: list.length, totalWeight, list };
}

function lintPercent(heapId, lorries, bales) {
  // Kapas weight is in quintals; bale weight is in kg — convert kapas to
  // kg before comparing, since these two are tracked in different units.
  const kapasWeightQtl = heapStats(heapId, lorries).totalWeight;
  const kapasWeightKg = kapasWeightQtl * 100;
  const bWeightKg = baleStats(heapId, bales).totalWeight;
  if (!kapasWeightKg) return null;
  return (bWeightKg / kapasWeightKg) * 100;
}

function heapKapasCost(heapId, lorries) {
  const list = lorries.filter((l) => l.heapId === heapId);
  const allPaid = list.every((l) => l.status === "paid");
  const cost = list.reduce((s, l) => s + (l.payment ? l.payment.rounded : 0), 0);
  return { cost, partial: !allPaid && list.some((l) => l.status === "paid") };
}

function heapCottonseedRevenue(heapId, cottonseedDispatches) {
  // Rate is now ₹ per quintal, applied uniformly to every heap the
  // dispatch drew from — so each heap simply earns rate × its own share.
  let revenue = 0;
  let weightQtl = 0;
  for (const d of cottonseedDispatches) {
    const alloc = (d.allocations || []).find((a) => a.heapId === heapId);
    if (!alloc) continue;
    weightQtl += alloc.weight;
    if (d.rate) revenue += d.rate * alloc.weight;
  }
  return { revenue, weightQtl };
}

const CANDY_TO_QUINTAL_RATE_FACTOR = 0.2812; // Per-Quintal Rate = Rate in Candy × 0.2812

function heapBaleRevenue(heapId, bales, baleDispatches) {
  // Bale weight is stored in kg; the dispatch lot's rate is ₹ per quintal
  // (whether entered directly or converted from a Candy rate), so convert
  // each bale's kg to quintals before applying the rate.
  let revenue = 0;
  let weightQtl = 0;
  const heapBales = bales.filter((b) => b.heapId === heapId && b.dispatched);
  for (const b of heapBales) {
    const qtl = b.weight / 100;
    weightQtl += qtl;
    const lot = baleDispatches.find((d) => d.id === b.dispatchLotId);
    if (lot && lot.rate) revenue += lot.rate * qtl;
  }
  return { revenue, weightQtl };
}

const STAGE_COLOR = {
  weighed: "#5B7FA6",
  moisture_recorded: "#C99A3C",
  rate_finalised: "#6D8E4E",
  paid: "#3E6B4F",
};

async function checkStorageHealth() {
  try {
    if (!window.storage || typeof window.storage.set !== "function") {
      return { ok: false, error: "window.storage is not available in this environment." };
    }
    const testKey = "healthcheck_ping";
    const testVal = `${Date.now()}`;
    const setRes = await window.storage.set(testKey, testVal, true);
    if (!setRes) return { ok: false, error: "storage.set() returned no result." };
    const getRes = await window.storage.get(testKey, true);
    if (!getRes || getRes.value !== testVal) {
      return { ok: false, error: "storage.get() did not return the value that was just written." };
    }
    return { ok: true, error: null };
  } catch (e) {
    console.error("storage health check failed", e);
    return { ok: false, error: (e && e.message) || String(e) };
  }
}

export default function App() {
  const [lang, setLang] = useState("en");
  const t = STRINGS[lang];
  const [session, setSession] = useState(null);
  const [users, setUsers] = useState([]);
  const [lorries, setLorries] = useState([]);
  const [heaps, setHeaps] = useState([]);
  const [bales, setBales] = useState([]);
  const [cottonseedDispatches, setCottonseedDispatches] = useState([]);
  const [baleDispatches, setBaleDispatches] = useState([]);
  const [settings, setSettings] = useState({ hammaliRate: 0 });
  const [loading, setLoading] = useState(true);
  const [view, setView] = useState("dashboard");
  const [storageOk, setStorageOk] = useState(null);
  const [storageError, setStorageError] = useState(null);
  const pollRef = useRef(null);

  useEffect(() => {
    let mounted = true;
    (async () => {
      const health = await checkStorageHealth();
      if (mounted) {
        setStorageOk(health.ok);
        setStorageError(health.error);
      }
      if (!health.ok) {
        if (mounted) setLoading(false);
        return;
      }
      let [data, s, h, b] = await Promise.all([loadLorries(), loadSettings(), loadHeaps(), loadBales()]);
      let [cd, bd, u] = await Promise.all([loadCottonseedDispatches(), loadBaleDispatches(), loadUsers()]);
      if (h.length === 0) {
        h = [{ id: `${Date.now()}`, heapNumber: 1, status: "open", startDate: new Date().toISOString() }];
        await saveHeaps(h);
      }
      if (mounted) {
        setLorries(data);
        setSettings(s);
        setHeaps(h);
        setBales(b);
        setCottonseedDispatches(cd);
        setBaleDispatches(bd);
        setUsers(u);
        setLoading(false);
      }
    })();
    pollRef.current = setInterval(async () => {
      const [data, s, h, b] = await Promise.all([loadLorries(), loadSettings(), loadHeaps(), loadBales()]);
      const [cd, bd, u] = await Promise.all([loadCottonseedDispatches(), loadBaleDispatches(), loadUsers()]);
      setLorries(data);
      setSettings(s);
      if (h.length > 0) setHeaps(h);
      setBales(b);
      setCottonseedDispatches(cd);
      setBaleDispatches(bd);
      setUsers(u);
    }, 4000);
    return () => {
      mounted = false;
      clearInterval(pollRef.current);
    };
  }, []);

  // Each role lands on its own task screen after login — nobody but the
  // owner defaults to (or can reach) the full ledger. A person can now hold
  // more than one role, so pick the "most senior" one they have for the
  // landing screen (owner first, then whichever else they were given).
  useEffect(() => {
    if (!session) return;
    const priority = ["owner", "weighment", "moisture", "payment", "bale", "dispatch"];
    const defaultViewFor = {
      owner: "dashboard",
      weighment: "new-entry",
      moisture: "moisture",
      payment: "payment",
      bale: "bale-entry",
      dispatch: "dispatch",
    };
    const roles = session.roles || [session.role];
    const primary = priority.find((r) => roles.includes(r)) || roles[0];
    setView(defaultViewFor[primary] || "dashboard");
  }, [session]);

  async function refreshLorries() {
    const data = await loadLorries();
    setLorries(data);
    return data;
  }
  async function refreshHeaps() {
    const h = await loadHeaps();
    setHeaps(h);
    return h;
  }
  async function refreshBales() {
    const b = await loadBales();
    setBales(b);
    return b;
  }

  async function addBale(heapId, weight) {
    try {
      const current = await refreshBales();
      const forHeap = current.filter((b) => b.heapId === heapId);
      const nextNumber = (forHeap.length ? Math.max(...forHeap.map((b) => b.baleNumber)) : 0) + 1;
      const record = {
        id: `${Date.now()}`,
        heapId,
        baleNumber: nextNumber,
        weight: parseFloat(weight),
        enteredBy: session.name,
        date: new Date().toISOString().slice(0, 10),
        time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
        dispatched: false,
        dispatchLotId: null,
      };
      const updated = [...current, record];
      setBales(updated);
      const ok = await saveBales(updated);
      if (!ok) { setBales(current); return { error: true }; }
      return { record };
    } catch (e) {
      console.error("addBale failed", e);
      return { error: true };
    }
  }

  async function refreshCottonseedDispatches() {
    const cd = await loadCottonseedDispatches();
    setCottonseedDispatches(cd);
    return cd;
  }
  async function refreshBaleDispatches() {
    const bd = await loadBaleDispatches();
    setBaleDispatches(bd);
    return bd;
  }

  async function addCottonseedDispatch({ lorryNumber, allocations }) {
    try {
      const current = await refreshCottonseedDispatches();
      const totalWeight = allocations.reduce((s, a) => s + a.weight, 0);
      const record = {
        id: `${Date.now()}`,
        lorryNumber: lorryNumber.trim(),
        allocations,
        totalWeight,
        rate: null,
        date: new Date().toISOString().slice(0, 10),
        enteredBy: session.name,
      };
      const updated = [record, ...current];
      setCottonseedDispatches(updated);
      const ok = await saveCottonseedDispatches(updated);
      if (!ok) { setCottonseedDispatches(current); return { error: true }; }
      return { record };
    } catch (e) {
      console.error("addCottonseedDispatch failed", e);
      return { error: true };
    }
  }

  async function setCottonseedRate(id, rate) {
    try {
      const current = await refreshCottonseedDispatches();
      const updated = current.map((d) => (d.id === id ? { ...d, rate: parseFloat(rate) } : d));
      setCottonseedDispatches(updated);
      const ok = await saveCottonseedDispatches(updated);
      if (!ok) { setCottonseedDispatches(current); return { error: true }; }
      return { ok: true };
    } catch (e) {
      console.error("setCottonseedRate failed", e);
      return { error: true };
    }
  }

  async function addBaleDispatchLot({ buyer, baleIds }) {
    try {
      const currentBales = await refreshBales();
      const currentLots = await refreshBaleDispatches();
      const selected = currentBales.filter((b) => baleIds.includes(b.id));
      const totalWeight = selected.reduce((s, b) => s + b.weight, 0);
      const lot = {
        id: `${Date.now()}`,
        buyer: buyer.trim(),
        baleIds,
        totalBales: selected.length,
        totalWeight,
        rate: null,
        date: new Date().toISOString().slice(0, 10),
        enteredBy: session.name,
      };
      const updatedLots = [lot, ...currentLots];
      const updatedBales = currentBales.map((b) =>
        baleIds.includes(b.id) ? { ...b, dispatched: true, dispatchLotId: lot.id } : b
      );
      setBaleDispatches(updatedLots);
      setBales(updatedBales);
      const [okLots, okBales] = await Promise.all([saveBaleDispatches(updatedLots), saveBales(updatedBales)]);
      if (!okLots || !okBales) { setBaleDispatches(currentLots); setBales(currentBales); return { error: true }; }
      return { record: lot };
    } catch (e) {
      console.error("addBaleDispatchLot failed", e);
      return { error: true };
    }
  }

  async function setBaleDispatchRate(id, rate, candyRate) {
    try {
      const current = await refreshBaleDispatches();
      const updated = current.map((d) =>
        d.id === id ? { ...d, rate: parseFloat(rate), candyRate: candyRate ? parseFloat(candyRate) : null } : d
      );
      setBaleDispatches(updated);
      const ok = await saveBaleDispatches(updated);
      if (!ok) { setBaleDispatches(current); return { error: true }; }
      return { ok: true };
    } catch (e) {
      console.error("setBaleDispatchRate failed", e);
      return { error: true };
    }
  }

  async function addLorry({ lorryNumber, farmerName, weight, rstNumber, manualEntry }) {
    try {
      const current = await refreshLorries();
      const currentHeaps = await refreshHeaps();
      const openHeap = currentHeaps.find((h) => h.status === "open");
      const now = new Date();
      const record = {
        id: `${Date.now()}`,
        lorryNumber: lorryNumber.trim() || `MANUAL-${now.getTime()}`,
        farmerName: farmerName.trim(),
        weight: parseFloat(weight),
        rst: `RST-${String(rstNumber).trim()}`, // required — the real number off the physical scale printout
        manualEntry: !!manualEntry,
        date: now.toISOString().slice(0, 10),
        time: now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
        timestamp: now.toISOString(),
        status: "weighed",
        moisture: null,
        moistureReadings: [],
        rate: null,
        payment: null,
        heapId: openHeap ? openHeap.id : null,
        enteredBy: session.name,
      };
      const updated = [record, ...current];
      setLorries(updated);
      const ok = await saveLorries(updated);
      if (!ok) { setLorries(current); return { error: true }; }
      return { record, heapNumber: openHeap ? openHeap.heapNumber : null };
    } catch (e) {
      console.error("addLorry failed", e);
      return { error: true };
    }
  }


  // Moisture is taken as several readings across the lorry's unload (every
  // 12–15 quintals or so in practice) and averaged. Readings accumulate
  // here without changing the lorry's stage — only the explicit "Finalize"
  // action (below) moves it on to rate negotiation, since only the person
  // holding the moisture meter knows when they've taken enough readings.
  async function addMoistureReading(id, value) {
    try {
      const current = await refreshLorries();
      const updated = current.map((l) => {
        if (l.id !== id) return l;
        const readings = [...(l.moistureReadings || []), { value: parseFloat(value), by: session.name, time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) }];
        return { ...l, moistureReadings: readings };
      });
      setLorries(updated);
      const ok = await saveLorries(updated);
      if (!ok) { setLorries(current); return { error: true }; }
      return { ok: true };
    } catch (e) {
      console.error("addMoistureReading failed", e);
      return { error: true };
    }
  }

  async function finalizeMoisture(id) {
    try {
      const current = await refreshLorries();
      const target = current.find((l) => l.id === id);
      const readings = (target && target.moistureReadings) || [];
      if (readings.length === 0) return { error: true, reason: "no-readings" };
      const avg = readings.reduce((s, r) => s + r.value, 0) / readings.length;
      const updated = current.map((l) =>
        l.id === id ? { ...l, moisture: Math.round(avg * 10) / 10, status: "moisture_recorded", moistureBy: session.name } : l
      );
      setLorries(updated);
      const ok = await saveLorries(updated);
      if (!ok) { setLorries(current); return { error: true }; }
      return { ok: true };
    } catch (e) {
      console.error("finalizeMoisture failed", e);
      return { error: true };
    }
  }

  async function finalizeRate(id, rate) {
    try {
      const current = await refreshLorries();
      const updated = current.map((l) =>
        l.id === id ? { ...l, rate: parseFloat(rate), status: "rate_finalised", rateBy: session.name } : l
      );
      setLorries(updated);
      const ok = await saveLorries(updated);
      if (!ok) { setLorries(current); return { error: true }; }
      return { ok: true };
    } catch (e) {
      console.error("finalizeRate failed", e);
      return { error: true };
    }
  }

  async function editLorry(id, updates) {
    // Owner-only correction of a lorry's details. Weight/moisture/rate can
    // only be changed before payment — once a lorry is paid, its financial
    // fields are locked so the payment slip record stays trustworthy.
    try {
      const current = await refreshLorries();
      const target = current.find((l) => l.id === id);
      if (!target) return { error: true };
      const locked = target.status === "paid";
      const safeUpdates = locked
        ? { lorryNumber: updates.lorryNumber, farmerName: updates.farmerName, rst: updates.rst }
        : updates;
      const updated = current.map((l) =>
        l.id === id ? { ...l, ...safeUpdates, editedBy: session.name, editedAt: new Date().toISOString() } : l
      );
      setLorries(updated);
      const ok = await saveLorries(updated);
      if (!ok) { setLorries(current); return { error: true }; }
      return { ok: true, locked };
    } catch (e) {
      console.error("editLorry failed", e);
      return { error: true };
    }
  }

  async function markPaid(id) {
    try {
      const current = await refreshLorries();
      const s = await loadSettings();
      const updated = current.map((l) => {
        if (l.id !== id) return l;
        const payment = computePayment(l, s.hammaliRate || 0);
        return { ...l, status: "paid", payment, paidBy: session.name };
      });
      setLorries(updated);
      const ok = await saveLorries(updated);
      if (!ok) { setLorries(current); return { error: true }; }
      return { ok: true };
    } catch (e) {
      console.error("markPaid failed", e);
      return { error: true };
    }
  }

  async function updateSettings(hammaliRate) {
    try {
      const previous = settings;
      const s = { ...settings, hammaliRate: parseFloat(hammaliRate) };
      setSettings(s);
      const ok = await saveSettings(s);
      if (!ok) { setSettings(previous); return { error: true }; }
      return { ok: true };
    } catch (e) {
      console.error("updateSettings failed", e);
      return { error: true };
    }
  }

  // Owner-only, PIN-gated. Wipes every transactional record (lorries, heaps,
  // bales, dispatches, hammali rate) and reseeds a fresh open Heap #1.
  // Registered users/logins are deliberately left untouched — that's a
  // separate action (see deleteUser below).
  async function resetAllData(pinOrConfirmText) {
    try {
      const me = users.find((u) => u.id === session.userId);
      if (me && me.pin) {
        if (pinOrConfirmText !== me.pin) return { error: true, reason: "pin" };
      } else {
        if (pinOrConfirmText !== "RESET") return { error: true, reason: "confirm" };
      }
      const freshHeap = { id: `${Date.now()}`, heapNumber: 1, status: "open", startDate: new Date().toISOString() };
      const results = await Promise.all([
        saveLorries([]),
        saveBales([]),
        saveCottonseedDispatches([]),
        saveBaleDispatches([]),
        saveSettings({ hammaliRate: 0 }),
        saveHeaps([freshHeap]),
      ]);
      if (results.some((r) => !r)) return { error: true, reason: "save" };
      setLorries([]);
      setBales([]);
      setCottonseedDispatches([]);
      setBaleDispatches([]);
      setSettings({ hammaliRate: 0 });
      setHeaps([freshHeap]);
      return { ok: true };
    } catch (e) {
      console.error("resetAllData failed", e);
      return { error: true, reason: "exception" };
    }
  }

  // Owner-only. Removes a registered login. Guards against deleting your
  // own currently-logged-in account to avoid an accidental self-lockout.
  async function deleteUser(userId) {
    try {
      if (userId === session.userId) return { error: true, reason: "self" };
      const current = await loadUsers();
      const updated = current.filter((u) => u.id !== userId);
      setUsers(updated);
      const ok = await saveUsers(updated);
      if (!ok) { setUsers(current); return { error: true }; }
      return { ok: true };
    } catch (e) {
      console.error("deleteUser failed", e);
      return { error: true };
    }
  }

  // Stops a heap accepting new lorries and starts the next one. The heap
  // moves to "pending" — not fully closed yet — since bale weighment and
  // dispatch still need to happen against it.
  async function closeHeapAndStartNext(heapId) {
    try {
      const current = await refreshHeaps();
      const nextNumber = Math.max(...current.map((h) => h.heapNumber), 0) + 1;
      const updated = current.map((h) =>
        h.id === heapId ? { ...h, status: "pending", pendingAt: new Date().toISOString(), pendingBy: session.name } : h
      );
      updated.push({ id: `${Date.now()}`, heapNumber: nextNumber, status: "open", startDate: new Date().toISOString() });
      setHeaps(updated);
      const ok = await saveHeaps(updated);
      if (!ok) { setHeaps(current); return { error: true }; }
      return { ok: true };
    } catch (e) {
      console.error("closeHeapAndStartNext failed", e);
      return { error: true };
    }
  }

  // Owner-only: mark a "pending" heap as fully, permanently closed. The
  // owner has final authority — this can be forced even if processing or
  // payment isn't complete, but the UI warns first (see HeapsView).
  async function forceCloseHeap(heapId) {
    try {
      const current = await refreshHeaps();
      const updated = current.map((h) =>
        h.id === heapId ? { ...h, status: "closed", closedAt: new Date().toISOString(), closedBy: session.name } : h
      );
      setHeaps(updated);
      const ok = await saveHeaps(updated);
      if (!ok) { setHeaps(current); return { error: true }; }
      return { ok: true };
    } catch (e) {
      console.error("forceCloseHeap failed", e);
      return { error: true };
    }
  }

  // Owner-only: which pending/closed heaps Bale Weighment Staff are
  // currently allowed to log bales against. More than one heap can be open
  // for processing at the same time — e.g. finishing yesterday's heap while
  // starting today's.
  async function toggleHeapProcessing(heapId) {
    try {
      const current = await refreshHeaps();
      const updated = current.map((h) =>
        h.id === heapId ? { ...h, processingOpen: !h.processingOpen } : h
      );
      setHeaps(updated);
      const ok = await saveHeaps(updated);
      if (!ok) { setHeaps(current); return { error: true }; }
      return { ok: true };
    } catch (e) {
      console.error("toggleHeapProcessing failed", e);
      return { error: true };
    }
  }

  async function retryStorageCheck() {
    setStorageOk(null);
    const health = await checkStorageHealth();
    setStorageOk(health.ok);
    setStorageError(health.error);
    if (health.ok) {
      setLoading(true);
      const [data, s, h, b] = await Promise.all([loadLorries(), loadSettings(), loadHeaps(), loadBales()]);
      const [cd, bd, u] = await Promise.all([loadCottonseedDispatches(), loadBaleDispatches(), loadUsers()]);
      setLorries(data);
      setSettings(s);
      setHeaps(h.length > 0 ? h : [{ id: `${Date.now()}`, heapNumber: 1, status: "open", startDate: new Date().toISOString() }]);
      setBales(b);
      setCottonseedDispatches(cd);
      setBaleDispatches(bd);
      setUsers(u);
      setLoading(false);
    }
  }

  async function registerUser({ name, roles, photo, pin }) {
    try {
      const current = await loadUsers();
      const record = {
        id: `${Date.now()}`,
        name: name.trim(),
        roles, // an array — a person can hold more than one responsibility
        role: roles[0], // kept in sync for any old code path that still reads .role
        photo: photo || null,
        pin: pin ? pin.trim() : null,
        createdAt: new Date().toISOString(),
        registeredBy: session ? session.name : "bootstrap",
      };
      const updated = [...current, record];
      setUsers(updated);
      const ok = await saveUsers(updated);
      if (!ok) { setUsers(current); return { error: true }; }
      return { ok: true, user: record };
    } catch (e) {
      console.error("registerUser failed", e);
      return { error: true };
    }
  }

  return (
    <div style={styles.appRoot}>
      <style>{css}</style>
      {storageOk === false ? (
        <StorageBrokenScreen lang={lang} onRetry={retryStorageCheck} error={storageError} />
      ) : !session ? (
        <LoginScreen t={t} lang={lang} setLang={setLang} users={users} onRegister={registerUser} onLogin={setSession} />
      ) : (
        <Shell t={t} lang={lang} setLang={setLang} session={session} onLogout={() => setSession(null)} view={view} setView={setView}>
          {loading ? (
            <div className="loading-note">{lang === "hi" ? "लेजर लोड हो रहा है…" : "Loading ledger…"}</div>
          ) : view === "dashboard" ? (
            <Dashboard t={t} lorries={lorries} heaps={heaps} settings={settings} session={session} onEditLorry={editLorry} />
          ) : view === "new-entry" ? (
            <NewEntry t={t} onAdd={addLorry} />
          ) : view === "moisture" ? (
            <MoistureEntry t={t} lorries={lorries} onAddReading={addMoistureReading} onFinalize={finalizeMoisture} />
          ) : view === "rate" ? (
            <RateNegotiation t={t} lorries={lorries} onFinalize={finalizeRate} />
          ) : view === "payment" ? (
            <PaymentSlips t={t} lorries={lorries} settings={settings} onMarkPaid={markPaid} session={session} />
          ) : view === "payment-ledger" ? (
            <PaymentLedgerView t={t} lorries={lorries} />
          ) : view === "heaps" ? (
            <HeapsView t={t} heaps={heaps} lorries={lorries} bales={bales} onCloseHeap={closeHeapAndStartNext} onForceClose={forceCloseHeap} onToggleProcessing={toggleHeapProcessing} />
          ) : view === "bale-entry" ? (
            <BaleEntry t={t} heaps={heaps} lorries={lorries} bales={bales} onAddBale={addBale} />
          ) : view === "dispatch" ? (
            <DispatchView
              t={t}
              heaps={heaps}
              bales={bales}
              cottonseedDispatches={cottonseedDispatches}
              onAddCottonseedDispatch={addCottonseedDispatch}
              onAddBaleDispatchLot={addBaleDispatchLot}
            />
          ) : view === "pnl" ? (
            <PnLView
              t={t}
              heaps={heaps}
              lorries={lorries}
              bales={bales}
              cottonseedDispatches={cottonseedDispatches}
              baleDispatches={baleDispatches}
              onSetCottonseedRate={setCottonseedRate}
              onSetBaleRate={setBaleDispatchRate}
            />
          ) : view === "raw-data" ? (
            <RawDataView t={t} lorries={lorries} heaps={heaps} bales={bales} settings={settings} cottonseedDispatches={cottonseedDispatches} baleDispatches={baleDispatches} />
          ) : (
            <SettingsView t={t} settings={settings} onSave={updateSettings} users={users} session={session} onReset={resetAllData} onDeleteUser={deleteUser} onRegister={registerUser} />
          )}
        </Shell>
      )}
    </div>
  );
}

function LangToggle({ lang, setLang, dark }) {
  const t = STRINGS[lang];
  return (
    <button className={dark ? "lang-toggle lang-toggle-dark" : "lang-toggle"} onClick={() => setLang(lang === "en" ? "hi" : "en")}>
      {t.lang}
    </button>
  );
}

// ---------- Login ----------
// ---------- Storage broken screen ----------
function StorageBrokenScreen({ lang, onRetry, error }) {
  const [retrying, setRetrying] = useState(false);
  const isHi = lang === "hi";

  async function handleRetry() {
    setRetrying(true);
    await onRetry();
    setRetrying(false);
  }

  return (
    <div className="login-wrap">
      <div className="login-card" style={{ borderColor: "#9C3B34", borderWidth: 2 }}>
        <div className="stamp" style={{ color: "#9C3B34", borderColor: "#9C3B34" }}>
          {isHi ? "स्टोरेज कनेक्ट नहीं हो पाया" : "STORAGE NOT CONNECTED"}
        </div>
        <h1 style={{ marginTop: 14 }}>
          {isHi ? "यह ऐप अभी सेव नहीं कर सकता" : "This app can't save right now"}
        </h1>
        <p className="sub">
          {isHi
            ? "नीचे बताया गया है कि असल में क्या गड़बड़ी हुई — यह किसी कोड बग से नहीं, बल्कि डेटाबेस कनेक्शन से जुड़ी समस्या है।"
            : "Here's the exact error the database connection returned — this is a connection issue, not a code bug."}
        </p>

        {error && (
          <pre className="raw-json" style={{ whiteSpace: "pre-wrap", marginBottom: 16 }}>{error}</pre>
        )}

        <div className="current-rate-note" style={{ marginBottom: 16 }}>
          {isHi ? (
            <>
              सबसे सामान्य कारण, ऊपर के मैसेज के हिसाब से:<br />
              • <strong>"Missing or insufficient permissions"</strong> → Firestore Rules जाँचें (Publish करना न भूलें)।<br />
              • <strong>नेटवर्क / ब्लॉक्ड</strong> → कोई ऐड-ब्लॉकर या फ़ायरवॉल Google की साइट्स को रोक रहा है, उसे बंद करें।<br />
              • <strong>Claude आर्टिफ़ैक्ट पर देख रहे हैं</strong> → Publish बटन दबाएँ और मिला लिंक खोलें, प्रीव्यू नहीं।<br />
              • अन्यथा: firebaseConfig.js में projectId/apiKey दोबारा जाँचें।
            </>
          ) : (
            <>
              Most common causes, based on the message above:<br />
              • <strong>"Missing or insufficient permissions"</strong> → check your Firestore Rules are published correctly.<br />
              • <strong>Network/blocked error</strong> → an ad-blocker or firewall may be blocking Google's servers — try disabling it or a different browser.<br />
              • <strong>Viewing a Claude artifact</strong> → click Publish in the artifact panel and open that link, not this preview.<br />
              • Otherwise: double-check the projectId/apiKey in firebaseConfig.js match your Firebase project exactly.
            </>
          )}
        </div>
        <button className="primary-btn" onClick={handleRetry} disabled={retrying}>
          {retrying ? (isHi ? "जाँच हो रही है…" : "Checking…") : (isHi ? "फिर कोशिश करें" : "Try again")}
        </button>
      </div>
    </div>
  );
}

// ---------- Login ----------
function LoginScreen({ t, lang, setLang, users, onRegister, onLogin }) {
  // Mode always tracks the current, real user count once it's loaded —
  // never gets stuck on the wrong screen if Firestore's data arrives a
  // moment after the first render.
  const [mode, setMode] = useState("picker");
  const [pendingUser, setPendingUser] = useState(null);
  const [pinInput, setPinInput] = useState("");
  const [pinError, setPinError] = useState(false);

  useEffect(() => {
    // Never interrupt someone already mid-way through entering their PIN —
    // only correct between "register" and "picker" as the real user count
    // loads in.
    setMode((prev) => (prev === "pin" ? prev : users.length === 0 ? "register" : "picker"));
  }, [users.length]);

  function selectUser(user) {
    const roles = user.roles || [user.role];
    if (user.pin) {
      setPendingUser(user);
      setPinInput("");
      setPinError(false);
      setMode("pin");
    } else {
      onLogin({ roles, role: roles[0], name: user.name, userId: user.id, photo: user.photo });
    }
  }

  function submitPin(e) {
    e.preventDefault();
    if (pinInput === pendingUser.pin) {
      const roles = pendingUser.roles || [pendingUser.role];
      onLogin({ roles, role: roles[0], name: pendingUser.name, userId: pendingUser.id, photo: pendingUser.photo });
    } else {
      setPinError(true);
      setPinInput("");
    }
  }

  return (
    <div className="login-wrap">
      <div className="login-card">
        <div className="login-card-top">
          <img src={LOGO_DATA_URI} alt="Balaji Cotspin" className="logo-login" />
          <LangToggle lang={lang} setLang={setLang} />
        </div>
        <div className="brand-block">
          <div className="brand-full">{t.brandFull}</div>
          <div className="brand-sub">{t.brandSub}</div>
        </div>

        {mode === "picker" && <UserPicker t={t} users={users} onSelect={selectUser} />}
        {mode === "register" && (
          // Self-registration only ever happens once — bootstrapping the
          // very first account, which becomes the owner. After that, only
          // the owner can register new people (Settings → Manage users),
          // so this screen never offers a "register" option again.
          <RegisterForm t={t} bootstrap onRegister={onRegister} onLogin={onLogin} onCancel={null} />
        )}
        {mode === "pin" && pendingUser && (
          <PinEntry
            t={t}
            user={pendingUser}
            pin={pinInput}
            setPin={setPinInput}
            error={pinError}
            onSubmit={submitPin}
            onBack={() => setMode("picker")}
          />
        )}
      </div>
    </div>
  );
}

function Avatar({ user, size }) {
  const style = { width: size, height: size };
  if (user.photo) {
    return <img src={user.photo} alt={user.name} className="avatar-img" style={style} />;
  }
  return (
    <div className="avatar-placeholder" style={style}>
      {(user.name || "?").trim().charAt(0).toUpperCase()}
    </div>
  );
}

const ROLE_LABEL_MAP_KEY = { owner: "roleOwner", weighment: "roleWeighment", moisture: "roleMoisture", payment: "rolePayment", bale: "roleBale", dispatch: "roleDispatch" };
function roleLabels(t, user) {
  const roles = user.roles || [user.role];
  return roles.map((r) => t[ROLE_LABEL_MAP_KEY[r]] || r).join(" + ");
}

function UserPicker({ t, users, onSelect }) {
  return (
    <div>
      <h1>{t.whoAreYouTitle}</h1>
      <p className="sub">{t.whoAreYouSub}</p>
      <div className="user-grid">
        {users.map((u) => (
          <button key={u.id} className="user-tile" onClick={() => onSelect(u)}>
            <Avatar user={u} size={56} />
            <div className="user-tile-name">{u.name}</div>
            <div className="user-tile-role">{roleLabels(t, u)}</div>
          </button>
        ))}
      </div>
      <p className="tiny-note" style={{ textAlign: "center", marginTop: 16 }}>{t.askOwnerToRegister}</p>
    </div>
  );
}

function RegisterForm({ t, onRegister, onLogin, onCancel, bootstrap, onDone }) {
  const [name, setName] = useState("");
  const [roles, setRoles] = useState(bootstrap ? ["owner"] : []);
  const [photo, setPhoto] = useState(null);
  const [pin, setPin] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(false);
  const fileInputRef = useRef(null);

  const ROLES = [
    { id: "owner", label: t.roleOwner, note: t.roleOwnerNote },
    { id: "weighment", label: t.roleWeighment, note: t.roleWeighmentNote },
    { id: "moisture", label: t.roleMoisture, note: t.roleMoistureNote },
    { id: "payment", label: t.rolePayment, note: t.rolePaymentNote },
    { id: "bale", label: t.roleBale, note: t.roleBaleNote },
    { id: "dispatch", label: t.roleDispatch, note: t.roleDispatchNote },
  ];

  function toggleRole(id) {
    setRoles((prev) => (prev.includes(id) ? prev.filter((r) => r !== id) : [...prev, id]));
  }

  async function handleFile(e) {
    const file = e.target.files[0];
    if (!file) return;
    try {
      const dataUrl = await resizePhotoFile(file);
      setPhoto(dataUrl);
    } catch (err) {
      console.error("photo resize failed", err);
    }
  }

  async function submit() {
    if (!name.trim() || roles.length === 0) return;
    // A PIN must be either left blank (no PIN) or exactly 4 digits — a
    // shorter PIN would register fine here but could never be entered at
    // login, since the login screen requires 4 digits before it even
    // enables the sign-in button. That mismatch would permanently lock the
    // person out of their own account, so it's rejected here instead.
    if (pin.trim() && pin.trim().length !== 4) {
      setError(true);
      return;
    }
    setSaving(true);
    setError(false);
    const result = await onRegister({ name, roles, photo, pin: pin.trim() || null });
    setSaving(false);
    if (result && result.error) {
      setError(true);
      return;
    }
    if (bootstrap) {
      onLogin({ roles: result.user.roles, role: result.user.roles[0], name: result.user.name, userId: result.user.id, photo: result.user.photo });
    } else {
      setName("");
      setRoles([]);
      setPhoto(null);
      setPin("");
      if (onDone) onDone(result.user);
    }
  }

  return (
    <div>
      <h1>{t.registerFormTitle}</h1>
      <p className="sub">{bootstrap ? t.registerFormSubBootstrap : t.registerFormSub}</p>

      <label className="field-label">{t.yourName}</label>
      <input className="text-input" placeholder={t.namePlaceholder} value={name} onChange={(e) => setName(e.target.value)} />

      <label className="field-label">{t.photoLabel}</label>
      <div className="photo-row">
        {photo ? <Avatar user={{ name, photo }} size={56} /> : <div className="avatar-placeholder" style={{ width: 56, height: 56 }}>{(name || "?").trim().charAt(0).toUpperCase() || "?"}</div>}
        <input ref={fileInputRef} type="file" accept="image/*" capture="user" style={{ display: "none" }} onChange={handleFile} />
        <button type="button" className="secondary-btn" onClick={() => fileInputRef.current && fileInputRef.current.click()}>
          {photo ? t.changePhotoBtn : t.addPhotoBtn}
        </button>
      </div>

      {!bootstrap && (
        <>
          <label className="field-label">{t.rolesLabel}</label>
          <p className="tiny-note" style={{ marginTop: -4 }}>{t.rolesMultiNote}</p>
          <div className="role-grid">
            {ROLES.map((r) => (
              <button key={r.id} className={"role-card" + (roles.includes(r.id) ? " role-card-active" : "")} onClick={() => toggleRole(r.id)}>
                <div className="role-title">{r.label}</div>
                <div className="role-note">{r.note}</div>
              </button>
            ))}
          </div>
        </>
      )}

      <label className="field-label">{t.pinLabel}</label>
      <input className="text-input" type="text" inputMode="numeric" maxLength={4} placeholder={t.pinPh} value={pin} onChange={(e) => setPin(e.target.value.replace(/\D/g, ""))} />
      <p className="tiny-note">{t.pinNote}</p>

      {error && (
        <div className="slip-note" style={{ background: "#FBEAEA", color: "#9C3B34", borderColor: "#E3B4B0" }}>
          {pin.trim() && pin.trim().length !== 4 ? t.pinMustBe4 : t.saveError}
        </div>
      )}

      <button className="primary-btn" disabled={!name.trim() || roles.length === 0 || saving} onClick={submit}>
        {saving ? t.saving : t.registerBtn}
      </button>
      {onCancel && (
        <button className="link-btn-dark" style={{ width: "100%", textAlign: "center", marginTop: 10 }} onClick={onCancel}>
          {t.backToPicker}
        </button>
      )}
    </div>
  );
}

function PinEntry({ t, user, pin, setPin, error, onSubmit, onBack }) {
  return (
    <div>
      <h1>{t.enterPinTitle}</h1>
      <div className="pin-user-row">
        <Avatar user={user} size={48} />
        <div>
          <div className="strong">{user.name}</div>
        </div>
      </div>
      <form onSubmit={onSubmit}>
        <input
          className="text-input"
          type="password"
          inputMode="numeric"
          maxLength={4}
          autoFocus
          value={pin}
          onChange={(e) => setPin(e.target.value.replace(/\D/g, ""))}
          placeholder={t.pinPh}
        />
        {error && <div className="slip-note" style={{ background: "#FBEAEA", color: "#9C3B34", borderColor: "#E3B4B0" }}>{t.pinWrong}</div>}
        <button className="primary-btn" type="submit" disabled={pin.length !== 4}>{t.pinSubmit}</button>
      </form>
      <button className="link-btn-dark" style={{ width: "100%", textAlign: "center", marginTop: 10 }} onClick={onBack}>
        {t.backToPicker}
      </button>
    </div>
  );
}

// ---------- Shell / nav ----------
function Shell({ t, lang, setLang, session, onLogout, view, setView, children }) {
  const roles = session.roles || [session.role];
  const has = (r) => roles.includes(r);
  const ROLE_LABEL = {
    owner: t.roleOwner, weighment: t.roleWeighment, moisture: t.roleMoisture,
    payment: t.rolePayment, bale: t.roleBale, dispatch: t.roleDispatch,
  };
  const roleLabel = roles.map((r) => ROLE_LABEL[r] || r).join(" + ");

  // The full ledger (every lorry, every heap's rate/lint%/processing info) is
  // owner-only. Other roles only ever see the screens for their own task(s)
  // — e.g. Payment Staff see just the pending-payments queue and the payment
  // ledger, never the whole ledger or any heap processing summary. A person
  // can hold more than one role, so tabs are the union of everything they
  // hold, not an exclusive single-role switch.
  const tabs = [];
  if (has("owner")) tabs.push({ id: "dashboard", label: t.ledgerTab });
  if (has("weighment")) tabs.push({ id: "new-entry", label: t.newLorryTab });
  if (has("moisture")) tabs.push({ id: "moisture", label: t.moistureTab });
  if (has("owner")) tabs.push({ id: "rate", label: t.rateTab });
  if (has("payment")) tabs.push({ id: "payment", label: t.paymentTab });
  if (has("owner") || has("payment")) tabs.push({ id: "payment-ledger", label: t.paymentLedgerTab });
  if (has("bale")) tabs.push({ id: "bale-entry", label: t.baleTab });
  if (has("dispatch")) tabs.push({ id: "dispatch", label: t.dispatchTab });
  if (has("owner")) tabs.push({ id: "heaps", label: t.heapsTab });
  if (has("owner")) tabs.push({ id: "pnl", label: t.pnlTab });
  if (has("owner")) tabs.push({ id: "raw-data", label: t.rawDataTab });
  if (has("owner")) tabs.push({ id: "settings", label: t.settingsTab });

  return (
    <div className="shell">
      <header className="topbar">
        <div className="brand">
          <img src={LOGO_DATA_URI} alt="Balaji Cotspin" className="logo-topbar" />
          <div className="brand-text">
            <span className="brand-full-sm">{t.brandFull}</span>
            <span className="brand-sub-sm">{t.brandSub}</span>
          </div>
        </div>
        <div className="who">
          {session.photo && <img src={session.photo} alt={session.name} className="who-avatar" />}
          <span className="who-name">{session.name}</span>
          <span className="who-role">{roleLabel}</span>
          <LangToggle lang={lang} setLang={setLang} dark />
          <button className="link-btn" onClick={onLogout}>{t.switchUser}</button>
        </div>
      </header>
      <nav className="tabs">
        {tabs.map((tb) => (
          <button key={tb.id} className={"tab" + (view === tb.id ? " tab-active" : "")} onClick={() => setView(tb.id)}>
            {tb.label}
          </button>
        ))}
      </nav>
      <main className="content">{children}</main>
    </div>
  );
}

// ---------- Current heap banner ----------
function CurrentHeapBanner({ t, heaps, lorries }) {
  const openHeap = heaps.find((h) => h.status === "open");
  if (!openHeap) return null;
  const stats = heapStats(openHeap.id, lorries);
  return (
    <div className="heap-banner">
      <div className="heap-banner-left">
        <div className="heap-banner-tag">{t.currentHeapBanner}</div>
        <div className="heap-banner-num">{t.heapNumberLabel} #{openHeap.heapNumber}</div>
      </div>
      <div className="heap-banner-stats">
        <div><span className="mono strong">{stats.totalWeight.toFixed(2)}</span> {t.qtl}</div>
        <div><span className="mono strong">{stats.avgRate ? "₹" + stats.avgRate.toFixed(0) : "—"}</span> {t.avgRateLabel.toLowerCase()}</div>
        <div><span className="mono strong">{stats.count}</span> {t.lorryCountLabel.toLowerCase()}</div>
      </div>
    </div>
  );
}

// ---------- Dashboard ----------
function Dashboard({ t, lorries, heaps, settings, session, onEditLorry }) {
  const pendingMoisture = lorries.filter((l) => l.status === "weighed").length;
  const readyForRate = lorries.filter((l) => l.status === "moisture_recorded").length;
  const awaitingPayment = lorries.filter((l) => l.status === "rate_finalised").length;
  const totalWeight = lorries.reduce((s, l) => s + (l.weight || 0), 0);
  const isOwner = session && (session.roles || [session.role]).includes("owner");

  const [editingId, setEditingId] = useState(null);
  const [slipId, setSlipId] = useState(null);

  const stageLabel = (status) =>
    status === "weighed" ? t.stageWeighed
    : status === "moisture_recorded" ? t.stageMoisture
    : status === "rate_finalised" ? t.stageRateFinalised
    : t.stagePaid;

  const heapNumberOf = (heapId) => heaps.find((h) => h.id === heapId)?.heapNumber ?? "—";
  const editingLorry = lorries.find((l) => l.id === editingId);
  const slipLorry = lorries.find((l) => l.id === slipId);

  return (
    <div>
      <CurrentHeapBanner t={t} heaps={heaps} lorries={lorries} />

      <div className="stat-row">
        <Stat label={t.statLorriesToday} value={lorries.length} />
        <Stat label={t.statAwaitingMoisture} value={pendingMoisture} accent={STAGE_COLOR.weighed} />
        <Stat label={t.statReadyForRate} value={readyForRate} accent={STAGE_COLOR.moisture_recorded} />
        <Stat label={t.statAwaitingPayment} value={awaitingPayment} accent={STAGE_COLOR.rate_finalised} />
        <Stat label={t.statTotalWeight} value={`${totalWeight.toFixed(2)} ${t.qtl}`} />
      </div>

      {lorries.length === 0 ? (
        <div className="empty-state">{t.emptyDashboard}</div>
      ) : (
        <div className="table-scroll"><table className="ledger-table ledger-table-main">
          <thead>
            <tr>
              <th>{t.thRst}</th>
              <th>{t.thLorryNo}</th>
              <th>{t.thFarmer}</th>
              <th className="num">{t.thWeight}</th>
              <th className="num">{t.thMoisture}</th>
              <th className="num">{t.thRate}</th>
              <th className="num">{t.thNetPay}</th>
              <th>{t.thHeap}</th>
              <th>{t.thStatus}</th>
              <th>{t.thTime}</th>
              {isOwner && <th>{t.thActions}</th>}
            </tr>
          </thead>
          <tbody>
            {lorries.map((l) => (
              <tr key={l.id}>
                <td className="mono" data-label={t.thRst}>{l.rst || "—"}</td>
                <td data-label={t.thLorryNo}>{l.lorryNumber}{l.manualEntry && <span className="manual-tag">{t.manualTagLabel}</span>}</td>
                <td data-label={t.thFarmer}>{l.farmerName || "—"}</td>
                <td className="num mono" data-label={t.thWeight}>{Number(l.weight).toFixed(2)}</td>
                <td className="num mono" data-label={t.thMoisture}>{l.moisture ?? "—"}</td>
                <td className="num mono" data-label={t.thRate}>{l.rate ?? "—"}</td>
                <td className="num mono" data-label={t.thNetPay}>{l.payment ? l.payment.rounded.toFixed(0) : "—"}</td>
                <td className="mono" data-label={t.thHeap}>#{heapNumberOf(l.heapId)}</td>
                <td data-label={t.thStatus}>
                  <span className="badge" style={{ background: STAGE_COLOR[l.status] }}>{stageLabel(l.status)}</span>
                </td>
                <td className="muted" data-label={t.thTime}>{l.date} · {l.time}</td>
                {isOwner && (
                  <td data-label={t.thActions}>
                    {l.status === "paid" ? (
                      <button className="link-btn-dark" onClick={() => setSlipId(l.id)}>{t.viewSlip}</button>
                    ) : (
                      <button className="link-btn-dark" onClick={() => setEditingId(l.id)}>{t.editBtn}</button>
                    )}
                  </td>
                )}
              </tr>
            ))}
          </tbody>
        </table></div>
      )}

      {editingLorry && (
        <EditLorryModal t={t} lorry={editingLorry} onClose={() => setEditingId(null)} onSave={onEditLorry} />
      )}
      {slipLorry && (
        <SlipModal t={t} lorry={slipLorry} settings={settings} readOnly onClose={() => setSlipId(null)} />
      )}
    </div>
  );
}

function EditLorryModal({ t, lorry, onClose, onSave }) {
  const locked = lorry.status === "paid";
  const [rst, setRst] = useState((lorry.rst || "").replace(/^RST-/, ""));
  const [lorryNumber, setLorryNumber] = useState(lorry.lorryNumber);
  const [farmerName, setFarmerName] = useState(lorry.farmerName || "");
  const [weight, setWeight] = useState(lorry.weight);
  const [moisture, setMoisture] = useState(lorry.moisture ?? "");
  const [rate, setRate] = useState(lorry.rate ?? "");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(false);

  async function submit(e) {
    e.preventDefault();
    setSaving(true);
    setError(false);
    const baseUpdates = { lorryNumber, farmerName, rst: `RST-${rst.trim()}` };
    const updates = locked
      ? baseUpdates
      : {
          ...baseUpdates,
          weight: parseFloat(weight),
          moisture: moisture === "" ? null : parseFloat(moisture),
          rate: rate === "" ? null : parseFloat(rate),
        };
    const result = await onSave(lorry.id, updates);
    setSaving(false);
    if (result && result.error) {
      setError(true);
      return;
    }
    onClose();
  }

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-card" onClick={(e) => e.stopPropagation()}>
        <div className="slip-header">
          <div className="stamp">{t.editEntryTitle}</div>
          <div className="mono">{lorry.rst || "—"}</div>
        </div>
        {locked && <p className="tiny-note">{t.editLockedNote}</p>}
        <form onSubmit={submit}>
          <label className="field-label">{t.enterRstLabel}</label>
          <div className="rst-prefix-row">
            <span className="rst-prefix">RST-</span>
            <input className="text-input" value={rst} onChange={(e) => setRst(e.target.value.replace(/\s/g, ""))} />
          </div>
          <label className="field-label">{t.lorryNumber}</label>
          <input className="text-input" value={lorryNumber} onChange={(e) => setLorryNumber(e.target.value)} />
          <label className="field-label">{t.farmerName}</label>
          <input className="text-input" value={farmerName} onChange={(e) => setFarmerName(e.target.value)} />
          <label className="field-label">{t.weightQtl}</label>
          <input className="text-input" type="number" step="0.01" value={weight} onChange={(e) => setWeight(e.target.value)} disabled={locked} />
          <label className="field-label">{t.moisturePh}</label>
          <input className="text-input" type="number" step="0.1" value={moisture} onChange={(e) => setMoisture(e.target.value)} disabled={locked} />
          <label className="field-label">{t.rateLabel}</label>
          <input className="text-input" type="number" step="1" value={rate} onChange={(e) => setRate(e.target.value)} disabled={locked} />
          {error && <div className="slip-note" style={{ background: "#FBEAEA", color: "#9C3B34", borderColor: "#E3B4B0" }}>{t.saveError}</div>}
          <div className="modal-actions">
            <button type="button" className="link-btn-dark" onClick={onClose}>{t.close}</button>
            <button className="primary-btn" style={{ marginTop: 0, width: "auto", padding: "10px 20px" }} type="submit" disabled={saving}>
              {saving ? t.saving : t.saveChanges}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

function Stat({ label, value, accent }) {
  return (
    <div className="stat-card">
      <div className="stat-value" style={accent ? { color: accent } : undefined}>{value}</div>
      <div className="stat-label">{label}</div>
    </div>
  );
}

// ---------- New lorry entry ----------
function NewEntry({ t, onAdd }) {
  const [manualMode, setManualMode] = useState(false);
  const [lorryNumber, setLorryNumber] = useState("");
  const [farmerName, setFarmerName] = useState("");
  const [weight, setWeight] = useState("");
  const [rstNumber, setRstNumber] = useState("");
  const [saved, setSaved] = useState(null);
  const [error, setError] = useState(false);
  const [saving, setSaving] = useState(false);

  const canSubmit = weight && rstNumber.trim() && (manualMode || lorryNumber.trim());

  async function submit(e) {
    e.preventDefault();
    if (!canSubmit) return;
    setSaving(true);
    setError(false);
    try {
      const result = await onAdd({ lorryNumber, farmerName, weight, rstNumber, manualEntry: manualMode });
      if (!result || result.error || !result.record) {
        setError(true);
        return;
      }
      setSaved(result);
      setLorryNumber("");
      setFarmerName("");
      setWeight("");
      setRstNumber("");
    } catch (e) {
      console.error("submit failed", e);
      setError(true);
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="form-card">
      <h2>{t.newEntryTitle}</h2>
      <p className="sub">{t.newEntrySub}</p>

      <label className="manual-toggle-row">
        <input type="checkbox" checked={manualMode} onChange={(e) => setManualMode(e.target.checked)} />
        <span>{t.manualEntryToggle}</span>
      </label>
      {manualMode && <p className="tiny-note">{t.manualEntryNote}</p>}

      <form onSubmit={submit}>
        <label className="field-label">{t.enterRstLabel}</label>
        <div className="rst-prefix-row">
          <span className="rst-prefix">RST-</span>
          <input className="text-input" value={rstNumber} onChange={(e) => setRstNumber(e.target.value.replace(/\s/g, ""))} placeholder={t.rstNumberOnlyPh} />
        </div>
        {!manualMode && (
          <>
            <label className="field-label">{t.lorryNumber}</label>
            <input className="text-input" value={lorryNumber} onChange={(e) => setLorryNumber(e.target.value)} placeholder={t.lorryNumberPh} />
            <label className="field-label">{t.farmerName}</label>
            <input className="text-input" value={farmerName} onChange={(e) => setFarmerName(e.target.value)} placeholder={t.farmerNamePh} />
          </>
        )}
        <label className="field-label">{t.weightQtl}</label>
        <input className="text-input" type="number" step="0.01" value={weight} onChange={(e) => setWeight(e.target.value)} placeholder={t.weightQtlPh} />
        <button className="primary-btn" type="submit" disabled={saving || !canSubmit}>{saving ? t.saving : t.saveEntry}</button>
        {!canSubmit && !saving && <p className="tiny-note">{t.rstRequiredNote}</p>}
      </form>
      {error && (
        <div className="slip-note" style={{ background: "#FBEAEA", color: "#9C3B34", borderColor: "#E3B4B0" }}>
          {t.saveError}
        </div>
      )}
      {saved && !error && (
        <div className="slip-note">
          {t.savedNote} <span className="mono">{saved.record.rst}</span>
          {saved.heapNumber && <> · {t.addedToHeap} <span className="mono">#{saved.heapNumber}</span></>}
        </div>
      )}
    </div>
  );
}

// ---------- Moisture entry ----------
function MoistureEntry({ t, lorries, onAddReading, onFinalize }) {
  const pending = lorries.filter((l) => l.status === "weighed");
  const [expanded, setExpanded] = useState(null);
  const [values, setValues] = useState({});
  const [savingId, setSavingId] = useState(null);
  const [finalizingId, setFinalizingId] = useState(null);
  const [errorId, setErrorId] = useState(null);

  async function addReading(id) {
    const v = values[id];
    if (!v) return;
    setSavingId(id);
    setErrorId(null);
    try {
      const result = await onAddReading(id, v);
      if (result && result.error) {
        setErrorId(id);
        return;
      }
      setValues((prev) => ({ ...prev, [id]: "" }));
    } catch (e) {
      console.error("addReading failed", e);
      setErrorId(id);
    } finally {
      setSavingId(null);
    }
  }

  async function finalize(id) {
    setFinalizingId(id);
    setErrorId(null);
    try {
      const result = await onFinalize(id);
      if (result && result.error) {
        setErrorId(id);
        return;
      }
    } catch (e) {
      console.error("finalize failed", e);
      setErrorId(id);
    } finally {
      setFinalizingId(null);
    }
  }

  return (
    <div>
      <h2 className="section-title">{t.moistureTitle}</h2>
      <p className="sub">{t.moistureSub}</p>
      {pending.length === 0 ? (
        <div className="empty-state">{t.emptyMoisture}</div>
      ) : (
        <div className="row-list">
          {pending.map((l) => {
            const readings = l.moistureReadings || [];
            const avg = readings.length ? readings.reduce((s, r) => s + r.value, 0) / readings.length : null;
            const isOpen = expanded === l.id;
            return (
              <div className="entry-row moisture-card" key={l.id} style={{ flexDirection: "column", alignItems: "stretch" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                  <div className="entry-info">
                    <div className="mono strong">{l.rst || "—"}</div>
                    <div className="muted">{l.lorryNumber} · {Number(l.weight).toFixed(2)} {t.qtl} · {l.farmerName || t.noName}</div>
                    <div className="muted entry-date">{l.date} · {l.time}</div>
                  </div>
                  <div className="mono net-preview" style={{ minWidth: 70 }}>
                    {avg !== null ? avg.toFixed(1) + "%" : "—"}
                  </div>
                  <button className="link-btn-dark" onClick={() => setExpanded(isOpen ? null : l.id)}>
                    {isOpen ? t.hideLorries : `${t.readingsCountLabel} (${readings.length})`}
                  </button>
                </div>

                {isOpen && (
                  <div style={{ marginTop: 10, paddingTop: 10, borderTop: "1px dashed #C3D4E6" }}>
                    {readings.length > 0 && (
                      <div className="reading-chip-row">
                        {readings.map((r, i) => (
                          <span className="reading-chip" key={i}>{r.value}%</span>
                        ))}
                      </div>
                    )}
                    <div style={{ display: "flex", gap: 8, marginTop: readings.length ? 10 : 0, flexWrap: "wrap" }}>
                      <input className="text-input small" type="number" step="0.1" placeholder={t.moisturePh}
                        value={values[l.id] || ""} onChange={(e) => setValues((prev) => ({ ...prev, [l.id]: e.target.value }))} />
                      <button className="secondary-btn" disabled={!values[l.id] || savingId === l.id} onClick={() => addReading(l.id)}>
                        {savingId === l.id ? t.saving : t.addReadingBtn}
                      </button>
                      <button className="primary-btn" style={{ marginTop: 0, width: "auto", padding: "9px 18px" }}
                        disabled={readings.length === 0 || finalizingId === l.id} onClick={() => finalize(l.id)}>
                        {finalizingId === l.id ? t.saving : `${t.finalizeMoistureBtn}${avg !== null ? ` (${avg.toFixed(1)}%)` : ""}`}
                      </button>
                    </div>
                    {errorId === l.id && (
                      <div className="slip-note" style={{ background: "#FBEAEA", color: "#9C3B34", borderColor: "#E3B4B0", marginTop: 8 }}>
                        {t.saveError}
                      </div>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

// ---------- Rate negotiation ----------
function RateNegotiation({ t, lorries, onFinalize }) {
  const pending = lorries.filter((l) => l.status === "moisture_recorded");
  const [values, setValues] = useState({});
  const [savingId, setSavingId] = useState(null);
  const [errorId, setErrorId] = useState(null);

  async function submit(id) {
    const v = values[id];
    if (!v) return;
    setSavingId(id);
    setErrorId(null);
    try {
      const result = await onFinalize(id, v);
      if (result && result.error) {
        setErrorId(id);
        return;
      }
      setValues((prev) => ({ ...prev, [id]: "" }));
    } catch (e) {
      console.error("submit failed", e);
      setErrorId(id);
    } finally {
      setSavingId(null);
    }
  }

  return (
    <div>
      <h2 className="section-title">{t.rateSectionTitle}</h2>
      <p className="sub">{t.rateSectionSub}</p>
      {pending.length === 0 ? (
        <div className="empty-state">{t.emptyRate}</div>
      ) : (
        <div className="row-list">
          {pending.map((l) => (
            <div className="entry-row" key={l.id}>
              <div className="entry-info">
                <div className="mono strong">{l.rst || "—"}</div>
                <div className="muted">{l.lorryNumber} · {Number(l.weight).toFixed(2)} {t.qtl} · {l.moisture}%</div>
                <div className="muted entry-date">{l.date} · {l.time}</div>
              </div>
              <input className="text-input small" type="number" step="1" placeholder={t.ratePh}
                value={values[l.id] || ""} onChange={(e) => setValues((prev) => ({ ...prev, [l.id]: e.target.value }))} />
              <button className="secondary-btn" disabled={!values[l.id] || savingId === l.id} onClick={() => submit(l.id)}>
                {savingId === l.id ? t.saving : errorId === l.id ? t.tryAgain : t.finalizeRate}
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ---------- Payment slips ----------
function PaymentSlips({ t, lorries, settings, onMarkPaid, session }) {
  const pending = lorries.filter((l) => l.status === "rate_finalised");
  const paidToday = lorries.filter((l) => l.status === "paid");
  const [openSlip, setOpenSlip] = useState(null);
  const [confirming, setConfirming] = useState(false);
  const [payError, setPayError] = useState(false);

  async function confirmPay(id) {
    setConfirming(true);
    setPayError(false);
    try {
      const result = await onMarkPaid(id);
      if (result && result.error) {
        setPayError(true);
        return;
      }
      // Deliberately leave the modal open — the lorry's status flips to
      // "paid" in the underlying data, which SlipModal detects on its own
      // and switches to a print-only view. This is what lets the payment
      // staff print a copy for the farmer immediately after confirming,
      // without having to find and reopen the slip separately.
    } catch (e) {
      console.error("confirmPay failed", e);
      setPayError(true);
    } finally {
      setConfirming(false);
    }
  }

  return (
    <div>
      <h2 className="section-title">{t.paymentSectionTitle}</h2>
      <p className="sub">{t.paymentSectionSub}</p>

      {pending.length === 0 ? (
        <div className="empty-state">{t.emptyPayment}</div>
      ) : (
        <div className="row-list">
          {pending.map((l) => {
            const preview = computePayment(l, settings.hammaliRate || 0);
            return (
              <div className="entry-row" key={l.id}>
                <div className="entry-info">
                  <div className="mono strong">{l.rst || "—"}</div>
                  <div className="muted">{l.lorryNumber} · {Number(l.weight).toFixed(2)} {t.qtl} · ₹{l.rate}{t.perQtl}</div>
                  <div className="muted entry-date">{l.date} · {l.time}</div>
                </div>
                <div className="mono net-preview">₹{preview.rounded.toFixed(0)}</div>
                <button className="secondary-btn" onClick={() => setOpenSlip(l.id)}>{t.generateSlip}</button>
              </div>
            );
          })}
        </div>
      )}

      {paidToday.length > 0 && (
        <>
          <h3 className="section-title small-title">{t.stagePaid}</h3>
          <div className="row-list">
            {paidToday.map((l) => (
              <div className="entry-row entry-row-paid" key={l.id}>
                <div className="entry-info">
                  <div className="mono strong">{l.rst || "—"}</div>
                  <div className="muted">{l.lorryNumber} · {t.paidNote} {l.paidBy}</div>
                  <div className="muted entry-date">{l.date} · {l.time}</div>
                </div>
                <div className="mono net-preview">₹{l.payment.rounded.toFixed(0)}</div>
              </div>
            ))}
          </div>
        </>
      )}

      {openSlip && (
        <SlipModal t={t} lorry={lorries.find((l) => l.id === openSlip)} settings={settings}
          onClose={() => setOpenSlip(null)} onConfirm={() => confirmPay(openSlip)} confirming={confirming} error={payError} />
      )}
    </div>
  );
}

// ---------- Payment ledger (Owner + Payment Staff) ----------
function PaymentLedgerView({ t, lorries }) {
  const todayStr = new Date().toISOString().slice(0, 10);
  const [fromDate, setFromDate] = useState(todayStr);
  const [toDate, setToDate] = useState(todayStr);

  const paidLorries = lorries
    .filter((l) => l.status === "paid" && l.payment && l.date >= fromDate && l.date <= toDate)
    .sort((a, b) => `${a.date} ${a.time}`.localeCompare(`${b.date} ${b.time}`));

  const totals = paidLorries.reduce(
    (acc, l) => {
      acc.weight += l.weight;
      acc.gross += l.payment.gross;
      acc.hammali += l.payment.hammali;
      acc.weighingCharge += l.payment.weighingCharge;
      acc.net += l.payment.rounded;
      return acc;
    },
    { weight: 0, gross: 0, hammali: 0, weighingCharge: 0, net: 0 }
  );
  const avgRate = totals.weight > 0 ? totals.gross / totals.weight : 0;

  return (
    <div>
      <h2 className="section-title">{t.paymentLedgerTitle}</h2>
      <p className="sub">{t.paymentLedgerSub}</p>

      <div className="ledger-filter-row no-print">
        <div>
          <label className="field-label">{t.fromDateLabel}</label>
          <input className="text-input" type="date" value={fromDate} onChange={(e) => setFromDate(e.target.value)} />
        </div>
        <div>
          <label className="field-label">{t.toDateLabel}</label>
          <input className="text-input" type="date" value={toDate} onChange={(e) => setToDate(e.target.value)} />
        </div>
        <button className="secondary-btn" onClick={() => { setFromDate(todayStr); setToDate(todayStr); }}>{t.todayBtn}</button>
        <button className="secondary-btn" onClick={() => window.print()}>{t.printBtn}</button>
      </div>
      <p className="tiny-note">{fromDate === toDate ? fromDate : `${fromDate} – ${toDate}`}</p>

      {paidLorries.length === 0 ? (
        <div className="empty-state">{t.noPaymentsInRange}</div>
      ) : (
        <div className="table-scroll"><table className="ledger-table">
          <thead>
            <tr>
              <th>{t.snoLabel}</th>
              <th>{t.thLorryNo}</th>
              <th className="num">{t.thWeight}</th>
              <th className="num">{t.thRate}</th>
              <th className="num">{t.grossLabel}</th>
              <th className="num">{t.hammaliLabel}</th>
              <th className="num">{t.weighingChargeLabel}</th>
              <th className="num">{t.netPaidLabel}</th>
            </tr>
          </thead>
          <tbody>
            {paidLorries.map((l, i) => (
              <tr key={l.id}>
                <td className="mono">{i + 1}</td>
                <td>{l.lorryNumber}</td>
                <td className="num mono">{Number(l.weight).toFixed(2)}</td>
                <td className="num mono">{l.rate}</td>
                <td className="num mono">{l.payment.gross.toFixed(2)}</td>
                <td className="num mono">{l.payment.hammali.toFixed(2)}</td>
                <td className="num mono">{l.payment.weighingCharge.toFixed(2)}</td>
                <td className="num mono">{l.payment.rounded.toFixed(0)}</td>
              </tr>
            ))}
          </tbody>
          <tfoot>
            <tr className="ledger-totals-row">
              <td colSpan={2}>{t.totalsLabel}</td>
              <td className="num mono">{totals.weight.toFixed(2)}</td>
              <td className="num mono">₹{avgRate.toFixed(2)}</td>
              <td className="num mono">{totals.gross.toFixed(2)}</td>
              <td className="num mono">{totals.hammali.toFixed(2)}</td>
              <td className="num mono">{totals.weighingCharge.toFixed(2)}</td>
              <td className="num mono">{totals.net.toFixed(0)}</td>
            </tr>
          </tfoot>
        </table></div>
      )}
    </div>
  );
}

function SlipModal({ t, lorry, settings, onClose, onConfirm, confirming, error, readOnly }) {
  // Isolate printing to just this modal — without this, printing would
  // include the whole page behind it (e.g. every other pending/paid
  // payment row), which is exactly the bug this fixes.
  useEffect(() => {
    document.body.classList.add("print-only-modal");
    return () => document.body.classList.remove("print-only-modal");
  }, []);

  if (!lorry) return null;
  const isPaid = lorry.status === "paid";
  // For an already-paid lorry, always show the exact figures that were
  // locked in at payment time — not a live recalculation, which could
  // drift if the hammali rate has changed since.
  const p = isPaid && lorry.payment ? lorry.payment : computePayment(lorry, settings.hammaliRate || 0);
  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-card" onClick={(e) => e.stopPropagation()}>
        <div className="slip-header">
          <div className="stamp">{t.slipTitle}</div>
          <div className="mono">{lorry.rst || "—"}</div>
        </div>
        <div className="slip-line"><span>{t.farmerLabel}</span><span>{lorry.farmerName || "—"}</span></div>
        <div className="slip-line"><span>{t.lorryLabel}</span><span>{lorry.lorryNumber}</span></div>
        <div className="slip-line"><span>{t.weightLabel}</span><span className="mono">{Number(lorry.weight).toFixed(2)} {t.qtl}</span></div>
        <div className="slip-line"><span>{t.rateLabelSlip}</span><span className="mono">₹{lorry.rate}{t.perQtl}</span></div>
        <div className="slip-divider" />
        <div className="slip-line"><span>{t.grossLabel}</span><span className="mono">₹{p.gross.toFixed(2)}</span></div>
        <div className="slip-line muted-line"><span>{t.hammaliLabel}</span><span className="mono">−₹{p.hammali.toFixed(2)}</span></div>
        <div className="slip-line muted-line"><span>{t.weighingChargeLabel}</span><span className="mono">−₹{p.weighingCharge.toFixed(2)}</span></div>
        <div className="slip-divider" />
        <div className="slip-line slip-total"><span>{t.netLabel}</span><span className="mono">₹{p.rounded.toFixed(0)}</span></div>
        {error && (
          <div className="slip-note" style={{ background: "#FBEAEA", color: "#9C3B34", borderColor: "#E3B4B0" }}>
            {t.saveError}
          </div>
        )}
        <div className="modal-actions">
          <button className="link-btn-dark no-print" onClick={onClose}>{t.close}</button>
          <button className="secondary-btn no-print" onClick={() => window.print()}>{t.printBtn}</button>
          {!readOnly && !isPaid && (
            <button className="primary-btn no-print" style={{ marginTop: 0, width: "auto", padding: "10px 20px" }} onClick={onConfirm} disabled={confirming}>
              {confirming ? t.saving : error ? t.tryAgain : t.markPaid}
            </button>
          )}
        </div>
        {!readOnly && isPaid && <p className="tiny-note no-print">{t.slipPaidPrintNote}</p>}
      </div>
    </div>
  );
}

// ---------- Heaps ----------
function HeapsView({ t, heaps, lorries, bales, onCloseHeap, onForceClose, onToggleProcessing }) {
  const openHeap = heaps.find((h) => h.status === "open");
  const pendingHeaps = heaps.filter((h) => h.status === "pending").sort((a, b) => b.heapNumber - a.heapNumber);
  const closedHeaps = heaps.filter((h) => h.status === "closed").sort((a, b) => b.heapNumber - a.heapNumber);
  const [confirmClose, setConfirmClose] = useState(false);
  const [closing, setClosing] = useState(false);
  const [expanded, setExpanded] = useState(null);
  const [closeError, setCloseError] = useState(false);

  const [forceCloseId, setForceCloseId] = useState(null);
  const [forceClosing, setForceClosing] = useState(false);
  const [forceCloseError, setForceCloseError] = useState(false);
  const [togglingId, setTogglingId] = useState(null);

  async function doToggleProcessing(heapId) {
    setTogglingId(heapId);
    try {
      await onToggleProcessing(heapId);
    } catch (e) {
      console.error("doToggleProcessing failed", e);
    } finally {
      setTogglingId(null);
    }
  }

  async function doClose() {
    setClosing(true);
    setCloseError(false);
    try {
      const result = await onCloseHeap(openHeap.id);
      if (result && result.error) {
        setCloseError(true);
        return;
      }
      setConfirmClose(false);
    } catch (e) {
      console.error("doClose failed", e);
      setCloseError(true);
    } finally {
      setClosing(false);
    }
  }

  async function doForceClose(heapId) {
    setForceClosing(true);
    setForceCloseError(false);
    try {
      const result = await onForceClose(heapId);
      if (result && result.error) {
        setForceCloseError(true);
        return;
      }
      setForceCloseId(null);
    } catch (e) {
      console.error("doForceClose failed", e);
      setForceCloseError(true);
    } finally {
      setForceClosing(false);
    }
  }

  const openStats = openHeap ? heapStats(openHeap.id, lorries) : null;

  function HeapDetailBody({ h }) {
    const stats = heapStats(h.id, lorries);
    const isExpanded = expanded === h.id;
    const bStatsLocal = baleStats(h.id, bales);
    return (
      <>
        <button className="link-btn-dark" onClick={() => setExpanded(isExpanded ? null : h.id)}>
          {isExpanded ? t.hideLorries : t.viewLorries}
        </button>
        {isExpanded && (
          <>
            <div className="table-scroll"><table className="ledger-table heap-mini-table">
              <thead>
                <tr><th>{t.thRst}</th><th>{t.thLorryNo}</th><th className="num">{t.heapDetailWeight}</th><th className="num">{t.heapDetailRate}</th><th>{t.thTime}</th></tr>
              </thead>
              <tbody>
                {stats.lorries.map((l) => (
                  <tr key={l.id}>
                    <td className="mono">{l.rst || "—"}</td>
                    <td>{l.lorryNumber}</td>
                    <td className="num mono">{Number(l.weight).toFixed(2)}</td>
                    <td className="num mono">{l.rate ?? t.noRateYet}</td>
                    <td className="muted">{l.date} · {l.time}</td>
                  </tr>
                ))}
              </tbody>
            </table></div>
            {bStatsLocal.count > 0 && (
              <div className="table-scroll"><table className="ledger-table heap-mini-table">
                <thead>
                  <tr><th>{t.baleNumberLabel}</th><th className="num">{t.baleWeightLabel}</th><th>{t.thTime}</th></tr>
                </thead>
                <tbody>
                  {bStatsLocal.list.map((b) => (
                    <tr key={b.id}>
                      <td className="mono">#{b.baleNumber}</td>
                      <td className="num mono">{b.weight}</td>
                      <td className="muted">{b.date} · {b.time}</td>
                    </tr>
                  ))}
                </tbody>
              </table></div>
            )}
          </>
        )}
      </>
    );
  }

  return (
    <div>
      <h2 className="section-title">{t.heapsSectionTitle}</h2>
      <p className="sub">{t.heapsSectionSub}</p>

      {openHeap && openStats && (
        <div className="heap-card heap-card-open">
          <div className="heap-card-top">
            <div className="heap-card-num">{t.heapNumberLabel} #{openHeap.heapNumber}</div>
            <span className="badge badge-open">{t.openBadge}</span>
          </div>
          <div className="heap-card-stats">
            <div><div className="heap-stat-value">{openStats.totalWeight.toFixed(2)}</div><div className="heap-stat-label">{t.totalQtlLabel}</div></div>
            <div><div className="heap-stat-value">{openStats.avgRate ? "₹" + openStats.avgRate.toFixed(0) : "—"}</div><div className="heap-stat-label">{t.avgRateLabel}</div></div>
            <div><div className="heap-stat-value">{openStats.count}</div><div className="heap-stat-label">{t.lorryCountLabel}</div></div>
          </div>

          {!confirmClose ? (
            <button className="secondary-btn" onClick={() => setConfirmClose(true)} disabled={openStats.count === 0}>
              {t.closeHeapBtn}
            </button>
          ) : (
            <div className="confirm-box">
              <p>{t.confirmCloseText} #{openHeap.heapNumber} {t.confirmCloseText2}</p>
              {closeError && (
                <div className="slip-note" style={{ background: "#FBEAEA", color: "#9C3B34", borderColor: "#E3B4B0" }}>
                  {t.saveError}
                </div>
              )}
              <div className="confirm-actions">
                <button className="link-btn-dark" onClick={() => setConfirmClose(false)}>{t.cancelBtn}</button>
                <button className="primary-btn" style={{ marginTop: 0, width: "auto", padding: "9px 18px", background: "#9C3B34" }} onClick={doClose} disabled={closing}>
                  {closing ? t.saving : closeError ? t.tryAgain : t.confirmBtn}
                </button>
              </div>
            </div>
          )}
        </div>
      )}

      <h3 className="section-title small-title">{t.pendingHeapsTitle}</h3>
      {pendingHeaps.length === 0 ? (
        <div className="empty-state">{t.noPendingHeaps}</div>
      ) : (
        <div className="row-list">
          {pendingHeaps.map((h) => {
            const stats = heapStats(h.id, lorries);
            const bStats = baleStats(h.id, bales);
            const lint = lintPercent(h.id, lorries, bales);
            const unfinished = bStats.count === 0 || stats.lorries.some((l) => l.status !== "paid");
            const confirming = forceCloseId === h.id;
            return (
              <div className="heap-card heap-card-pending" key={h.id}>
                <div className="heap-card-top">
                  <div className="heap-card-num">{t.heapNumberLabel} #{h.heapNumber}</div>
                  <span className="badge" style={{ background: "#C99A3C" }}>{t.pendingBadge}</span>
                </div>
                <div className="heap-card-stats">
                  <div><div className="heap-stat-value">{stats.totalWeight.toFixed(2)}</div><div className="heap-stat-label">{t.totalQtlLabel}</div></div>
                  <div><div className="heap-stat-value">{stats.avgRate ? "₹" + stats.avgRate.toFixed(0) : "—"}</div><div className="heap-stat-label">{t.avgRateLabel}</div></div>
                  <div><div className="heap-stat-value">{stats.count}</div><div className="heap-stat-label">{t.lorryCountLabel}</div></div>
                  <div><div className="heap-stat-value">{bStats.count}</div><div className="heap-stat-label">{t.totalBalesLabel}</div></div>
                  <div><div className="heap-stat-value">{lint ? lint.toFixed(2) + "%" : "—"}</div><div className="heap-stat-label">{t.lintPercentLabel}</div></div>
                </div>
                <HeapDetailBody h={h} />
                <div className="processing-toggle-row">
                  <span className={"badge " + (h.processingOpen ? "badge-open" : "")} style={!h.processingOpen ? { background: "#8A94A3" } : undefined}>
                    {h.processingOpen ? t.processingOpenBadge : t.processingClosedBadge}
                  </span>
                  <button className="link-btn-dark" disabled={togglingId === h.id} onClick={() => doToggleProcessing(h.id)}>
                    {togglingId === h.id ? t.saving : h.processingOpen ? t.stopProcessingBtn : t.openProcessingBtn}
                  </button>
                </div>
                {!confirming ? (
                  <button className="secondary-btn" style={{ marginTop: 10 }} onClick={() => setForceCloseId(h.id)}>{t.markFullyClosedBtn}</button>
                ) : (
                  <div className="confirm-box" style={{ marginTop: 10 }}>
                    <p>{unfinished ? t.forceCloseWarning : t.forceCloseConfirmText}</p>
                    {forceCloseError && (
                      <div className="slip-note" style={{ background: "#FBEAEA", color: "#9C3B34", borderColor: "#E3B4B0" }}>
                        {t.saveError}
                      </div>
                    )}
                    <div className="confirm-actions">
                      <button className="link-btn-dark" onClick={() => setForceCloseId(null)}>{t.cancelBtn}</button>
                      <button className="primary-btn" style={{ marginTop: 0, width: "auto", padding: "9px 18px", background: "#9C3B34" }} onClick={() => doForceClose(h.id)} disabled={forceClosing}>
                        {forceClosing ? t.saving : forceCloseError ? t.tryAgain : t.confirmBtn}
                      </button>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      <h3 className="section-title small-title">{t.heapHistoryTitle}</h3>
      {closedHeaps.length === 0 ? (
        <div className="empty-state">{t.noClosedHeaps}</div>
      ) : (
        <div className="row-list">
          {closedHeaps.map((h) => {
            const stats = heapStats(h.id, lorries);
            const bStats = baleStats(h.id, bales);
            const lint = lintPercent(h.id, lorries, bales);
            return (
              <div className="heap-card" key={h.id}>
                <div className="heap-card-top">
                  <div className="heap-card-num">{t.heapNumberLabel} #{h.heapNumber}</div>
                  <span className="badge" style={{ background: "#64748B" }}>{t.closedBadge}</span>
                </div>
                <div className="heap-card-stats">
                  <div><div className="heap-stat-value">{stats.totalWeight.toFixed(2)}</div><div className="heap-stat-label">{t.totalQtlLabel}</div></div>
                  <div><div className="heap-stat-value">{stats.avgRate ? "₹" + stats.avgRate.toFixed(0) : "—"}</div><div className="heap-stat-label">{t.avgRateLabel}</div></div>
                  <div><div className="heap-stat-value">{stats.count}</div><div className="heap-stat-label">{t.lorryCountLabel}</div></div>
                  <div><div className="heap-stat-value">{bStats.count}</div><div className="heap-stat-label">{t.totalBalesLabel}</div></div>
                  <div><div className="heap-stat-value">{lint ? lint.toFixed(2) + "%" : "—"}</div><div className="heap-stat-label">{t.lintPercentLabel}</div></div>
                </div>
                <HeapDetailBody h={h} />
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

// ---------- Bale entry ----------
function BaleEntry({ t, heaps, lorries, bales, onAddBale }) {
  // Bale Weighment Staff can only see heaps the owner has explicitly opened
  // for processing today — not every pending/closed heap. This also keeps
  // the heap's processing summary (lint %, kapas-in-heap) out of their
  // view entirely; that stays owner-only, visible in the Heaps tab.
  const openForProcessing = heaps.filter((h) => h.status !== "open" && h.processingOpen).sort((a, b) => b.heapNumber - a.heapNumber);
  const [heapId, setHeapId] = useState(openForProcessing[0]?.id || "");
  const [weight, setWeight] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(false);

  useEffect(() => {
    if (!openForProcessing.find((h) => h.id === heapId)) {
      setHeapId(openForProcessing[0]?.id || "");
    }
  }, [openForProcessing.map((h) => h.id).join(",")]);

  const selectedHeap = openForProcessing.find((h) => h.id === heapId);
  const bStats = selectedHeap ? baleStats(selectedHeap.id, bales) : null;

  async function submit(e) {
    e.preventDefault();
    if (!heapId || !weight) return;
    setSaving(true);
    setError(false);
    try {
      const result = await onAddBale(heapId, weight);
      if (!result || result.error || !result.record) {
        setError(true);
        return;
      }
      setWeight("");
    } catch (e) {
      console.error("submit failed", e);
      setError(true);
    } finally {
      setSaving(false);
    }
  }

  return (
    <div>
      <h2 className="section-title">{t.baleSectionTitle}</h2>
      <p className="sub">{t.baleSectionSub}</p>

      {openForProcessing.length === 0 ? (
        <div className="empty-state">{t.noHeapsOpenForProcessing}</div>
      ) : (
        <>
          {openForProcessing.length > 1 && (
            <>
              <label className="field-label">{t.selectHeapLabel}</label>
              <select className="text-input" value={heapId} onChange={(e) => setHeapId(e.target.value)} style={{ maxWidth: 280, marginBottom: 18 }}>
                {openForProcessing.map((h) => (
                  <option key={h.id} value={h.id}>{t.heapNumberLabel} #{h.heapNumber}</option>
                ))}
              </select>
            </>
          )}

          {selectedHeap && bStats && (
            <>
              <div className="heap-card" style={{ marginBottom: 20 }}>
                <div className="heap-card-top">
                  <div className="heap-card-num">{t.heapNumberLabel} #{selectedHeap.heapNumber}</div>
                </div>
              </div>

              <div className="form-card" style={{ maxWidth: 340, padding: 20 }}>
                <form onSubmit={submit}>
                  <label className="field-label">{t.baleWeightLabel}</label>
                  <input className="text-input" type="number" step="0.1" value={weight} onChange={(e) => setWeight(e.target.value)} placeholder={t.baleWeightPh} />
                  <button className="primary-btn" type="submit" disabled={saving || !weight}>
                    {saving ? t.saving : error ? t.tryAgain : `${t.addBale} — ${t.baleNumberLabel}${bStats.count + 1}`}
                  </button>
                  {error && (
                    <div className="slip-note" style={{ background: "#FBEAEA", color: "#9C3B34", borderColor: "#E3B4B0" }}>
                      {t.saveError}
                    </div>
                  )}
                </form>
              </div>

              <h3 className="section-title small-title">{t.balesEnteredTitle}</h3>
              {bStats.count === 0 ? (
                <div className="empty-state">{t.noBalesYet}</div>
              ) : (
                <div className="table-scroll"><table className="ledger-table">
                  <thead>
                    <tr><th>{t.baleNumberLabel}</th><th className="num">{t.baleWeightLabel}</th><th>{t.thTime}</th></tr>
                  </thead>
                  <tbody>
                    {[...bStats.list].reverse().map((b) => (
                      <tr key={b.id}>
                        <td className="mono">#{b.baleNumber}</td>
                        <td className="num mono">{b.weight}</td>
                        <td className="muted">{b.date} · {b.time}</td>
                      </tr>
                    ))}
                  </tbody>
                </table></div>
              )}
            </>
          )}
        </>
      )}
    </div>
  );
}

// ---------- Dispatch (cottonseed + bales) ----------
function DispatchView({ t, heaps, bales, cottonseedDispatches, onAddCottonseedDispatch, onAddBaleDispatchLot }) {
  const [sub, setSub] = useState("cottonseed");
  return (
    <div>
      <div className="subtab-row">
        <button className={"subtab" + (sub === "cottonseed" ? " subtab-active" : "")} onClick={() => setSub("cottonseed")}>{t.cottonseedSubTab}</button>
        <button className={"subtab" + (sub === "bales" ? " subtab-active" : "")} onClick={() => setSub("bales")}>{t.balesSubTab}</button>
      </div>
      {sub === "cottonseed" ? (
        <CottonseedDispatchPanel t={t} heaps={heaps} cottonseedDispatches={cottonseedDispatches} onAdd={onAddCottonseedDispatch} />
      ) : (
        <BaleDispatchPanel t={t} heaps={heaps} bales={bales} onAdd={onAddBaleDispatchLot} />
      )}
    </div>
  );
}

function CottonseedDispatchPanel({ t, heaps, cottonseedDispatches, onAdd }) {
  const closedHeaps = heaps.filter((h) => h.status !== "open").sort((a, b) => b.heapNumber - a.heapNumber);
  const [lorryNumber, setLorryNumber] = useState("");
  const [rows, setRows] = useState([{ heapId: closedHeaps[0]?.id || "", weight: "" }]);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(false);

  const total = rows.reduce((s, r) => s + (parseFloat(r.weight) || 0), 0);

  function updateRow(i, field, value) {
    setRows((prev) => prev.map((r, idx) => (idx === i ? { ...r, [field]: value } : r)));
  }
  function addRow() {
    setRows((prev) => [...prev, { heapId: closedHeaps[0]?.id || "", weight: "" }]);
  }
  function removeRow(i) {
    setRows((prev) => prev.filter((_, idx) => idx !== i));
  }

  async function submit(e) {
    e.preventDefault();
    const allocations = rows.filter((r) => r.heapId && r.weight).map((r) => ({ heapId: r.heapId, weight: parseFloat(r.weight) }));
    if (!lorryNumber.trim() || allocations.length === 0) return;
    setSaving(true);
    setError(false);
    try {
      const result = await onAdd({ lorryNumber, allocations });
      if (!result || result.error || !result.record) {
        setError(true);
        return;
      }
      setLorryNumber("");
      setRows([{ heapId: closedHeaps[0]?.id || "", weight: "" }]);
    } catch (e) {
      console.error("submit failed", e);
      setError(true);
    } finally {
      setSaving(false);
    }
  }

  const heapLabel = (id) => "#" + (heaps.find((h) => h.id === id)?.heapNumber ?? "?");

  return (
    <div>
      <div className="form-card" style={{ maxWidth: 480 }}>
        <h2>{t.cottonseedFormTitle}</h2>
        <p className="sub">{t.cottonseedFormSub}</p>
        {closedHeaps.length === 0 ? (
          <div className="empty-state">{t.noClosedHeapsForBales}</div>
        ) : (
          <form onSubmit={submit}>
            <label className="field-label">{t.lorryNoLabel}</label>
            <input className="text-input" value={lorryNumber} onChange={(e) => setLorryNumber(e.target.value)} placeholder={t.lorryNoPh} />

            <label className="field-label" style={{ marginTop: 18 }}>{t.allocationsTitle}</label>
            {rows.map((r, i) => (
              <div className="alloc-row" key={i}>
                <select className="text-input" value={r.heapId} onChange={(e) => updateRow(i, "heapId", e.target.value)}>
                  {closedHeaps.map((h) => (<option key={h.id} value={h.id}>{t.allocHeapLabel} #{h.heapNumber}</option>))}
                </select>
                <input className="text-input" type="number" step="0.01" placeholder={t.allocWeightLabel} value={r.weight} onChange={(e) => updateRow(i, "weight", e.target.value)} />
                {rows.length > 1 && <button type="button" className="link-btn-dark" onClick={() => removeRow(i)}>{t.removeRow}</button>}
              </div>
            ))}
            <button type="button" className="link-btn-dark" onClick={addRow}>{t.addAllocationRow}</button>

            <div className="total-line">{t.totalDispatchWeight}: <span className="mono strong">{total.toFixed(2)} {t.qtl}</span></div>

            <button className="primary-btn" type="submit" disabled={saving || total === 0 || !lorryNumber.trim()}>
              {saving ? t.saving : error ? t.tryAgain : t.saveDispatch}
            </button>
            {error && (
              <div className="slip-note" style={{ background: "#FBEAEA", color: "#9C3B34", borderColor: "#E3B4B0" }}>
                {t.saveError}
              </div>
            )}
          </form>
        )}
      </div>

      <h3 className="section-title small-title">{t.recentDispatchesTitle}</h3>
      {cottonseedDispatches.length === 0 ? (
        <div className="empty-state">{t.noDispatchesYet}</div>
      ) : (
        <div className="row-list">
          {cottonseedDispatches.map((d) => (
            <div className="entry-row" key={d.id}>
              <div className="entry-info">
                <div className="strong">{d.lorryNumber}</div>
                <div className="muted">{d.allocations.map((a) => `${heapLabel(a.heapId)}: ${a.weight} ${t.qtl}`).join(" + ")} · {d.totalWeight.toFixed(2)} {t.qtl}</div>
                <div className="muted entry-date">{d.date}</div>
              </div>
              {d.rate ? <div className="mono net-preview">₹{d.rate}{t.perQtl}</div> : <span className="badge" style={{ background: "#C99A3C" }}>{t.awaitingPriceBadge}</span>}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function BaleDispatchPanel({ t, heaps, bales, onAdd }) {
  const undispatched = bales.filter((b) => !b.dispatched);
  const closedHeapIds = new Set(heaps.filter((h) => h.status !== "open").map((h) => h.id));
  const eligible = undispatched.filter((b) => closedHeapIds.has(b.heapId));
  const [buyer, setBuyer] = useState("");
  const [selected, setSelected] = useState([]);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(false);

  const grouped = {};
  for (const b of eligible) {
    if (!grouped[b.heapId]) grouped[b.heapId] = [];
    grouped[b.heapId].push(b);
  }

  const heapLabel = (id) => "#" + (heaps.find((h) => h.id === id)?.heapNumber ?? "?");

  function toggle(id) {
    setSelected((prev) => (prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]));
  }

  async function submit(e) {
    e.preventDefault();
    if (!buyer.trim() || selected.length === 0) return;
    setSaving(true);
    setError(false);
    try {
      const result = await onAdd({ buyer, baleIds: selected });
      if (!result || result.error || !result.record) {
        setError(true);
        return;
      }
      setBuyer("");
      setSelected([]);
    } catch (e) {
      console.error("submit failed", e);
      setError(true);
    } finally {
      setSaving(false);
    }
  }

  const selectedWeight = eligible.filter((b) => selected.includes(b.id)).reduce((s, b) => s + b.weight, 0);

  return (
    <div>
      <div className="form-card" style={{ maxWidth: 520 }}>
        <h2>{t.balesFormTitle}</h2>
        <p className="sub">{t.balesFormSub}</p>
        {eligible.length === 0 ? (
          <div className="empty-state">{t.noUndispatchedBales}</div>
        ) : (
          <form onSubmit={submit}>
            <label className="field-label">{t.buyerLabel}</label>
            <input className="text-input" value={buyer} onChange={(e) => setBuyer(e.target.value)} placeholder={t.buyerPh} />

            <div className="bale-check-list">
              {Object.entries(grouped).map(([heapId, list]) => (
                <div key={heapId} className="bale-check-group">
                  <div className="bale-check-heap">{t.heapNumberLabel} {heapLabel(heapId)}</div>
                  {list.map((b) => (
                    <label className="bale-check-row" key={b.id}>
                      <input type="checkbox" checked={selected.includes(b.id)} onChange={() => toggle(b.id)} />
                      <span className="mono">#{b.baleNumber}</span>
                      <span className="mono muted">{b.weight} kg</span>
                    </label>
                  ))}
                </div>
              ))}
            </div>

            <div className="total-line">{t.selectedBalesSummary}: <span className="mono strong">{selected.length} {t.balesSelectedCount}</span> · {selectedWeight.toFixed(1)} kg</div>

            <button className="primary-btn" type="submit" disabled={saving || selected.length === 0 || !buyer.trim()}>
              {saving ? t.saving : error ? t.tryAgain : t.saveBaleDispatch}
            </button>
            {error && (
              <div className="slip-note" style={{ background: "#FBEAEA", color: "#9C3B34", borderColor: "#E3B4B0" }}>
                {t.saveError}
              </div>
            )}
          </form>
        )}
      </div>
    </div>
  );
}

// ---------- P&L ----------
function PnLView({ t, heaps, lorries, bales, cottonseedDispatches, baleDispatches, onSetCottonseedRate, onSetBaleRate }) {
  const pendingCottonseed = cottonseedDispatches.filter((d) => !d.rate);
  const pendingBales = baleDispatches.filter((d) => !d.rate);
  const pricedCottonseed = cottonseedDispatches.filter((d) => d.rate);
  const pricedBales = baleDispatches.filter((d) => d.rate);
  const closedHeaps = heaps.filter((h) => h.status !== "open").sort((a, b) => a.heapNumber - b.heapNumber);

  const [csValues, setCsValues] = useState({});
  const [baleValues, setBaleValues] = useState({}); // { [id]: { mode: 'quintal'|'candy', value: string } }
  const [savingId, setSavingId] = useState(null);
  const [errorId, setErrorId] = useState(null);
  const [invoice, setInvoice] = useState(null); // { kind: 'cottonseed'|'bale', record }

  async function saveCs(id) {
    if (!csValues[id]) return;
    setSavingId(id);
    setErrorId(null);
    try {
      const result = await onSetCottonseedRate(id, csValues[id]);
      if (result && result.error) {
        setErrorId(id);
        return;
      }
      setCsValues((p) => ({ ...p, [id]: "" }));
    } catch (e) {
      console.error("saveCs failed", e);
      setErrorId(id);
    } finally {
      setSavingId(null);
    }
  }

  function baleRowState(id) {
    return baleValues[id] || { mode: "quintal", value: "" };
  }
  function setBaleRowValue(id, value) {
    setBaleValues((p) => ({ ...p, [id]: { ...baleRowState(id), value } }));
  }
  function setBaleRowMode(id, mode) {
    setBaleValues((p) => ({ ...p, [id]: { ...baleRowState(id), mode, value: "" } }));
  }
  function effectiveBaleRate(id) {
    const row = baleRowState(id);
    const num = parseFloat(row.value);
    if (isNaN(num)) return null;
    return row.mode === "candy" ? num * CANDY_TO_QUINTAL_RATE_FACTOR : num;
  }

  async function saveBale(id) {
    const row = baleRowState(id);
    const rate = effectiveBaleRate(id);
    if (!row.value || rate === null) return;
    setSavingId(id);
    setErrorId(null);
    try {
      const result = await onSetBaleRate(id, rate, row.mode === "candy" ? row.value : null);
      if (result && result.error) {
        setErrorId(id);
        return;
      }
      setBaleValues((p) => ({ ...p, [id]: { mode: row.mode, value: "" } }));
    } catch (e) {
      console.error("saveBale failed", e);
      setErrorId(id);
    } finally {
      setSavingId(null);
    }
  }

  return (
    <div>
      <h2 className="section-title">{t.pnlSectionTitle}</h2>
      <p className="sub">{t.pnlSectionSub}</p>

      <h3 className="section-title small-title">{t.pendingPricingTitle}</h3>
      {pendingCottonseed.length === 0 && pendingBales.length === 0 ? (
        <div className="empty-state">{t.noPendingPricing}</div>
      ) : (
        <div className="row-list">
          {pendingCottonseed.map((d) => {
            const csAmount = csValues[d.id] ? parseFloat(csValues[d.id]) * d.totalWeight : null;
            return (
              <div className="entry-row entry-row-pricing" key={d.id}>
                <div className="entry-info">
                  <div className="strong">{t.cottonseedSubTab}: {d.lorryNumber}</div>
                  <div className="muted">{d.totalWeight.toFixed(2)} {t.qtl}</div>
                  <div className="muted entry-date">{d.date}</div>
                </div>
                <div className="pricing-input-col">
                  <input className="text-input small" type="number" placeholder={t.ratePh} value={csValues[d.id] || ""} onChange={(e) => setCsValues((p) => ({ ...p, [d.id]: e.target.value }))} />
                  {csAmount !== null && !isNaN(csAmount) && <div className="live-total">{t.totalPreviewLabel} ₹{csAmount.toFixed(0)}</div>}
                </div>
                <button className="secondary-btn" disabled={!csValues[d.id] || savingId === d.id} onClick={() => saveCs(d.id)}>
                  {savingId === d.id ? t.saving : errorId === d.id ? t.tryAgain : t.setRateBtn}
                </button>
              </div>
            );
          })}
          {pendingBales.map((d) => {
            const row = baleRowState(d.id);
            const rate = effectiveBaleRate(d.id);
            const qtl = d.totalWeight / 100;
            const amount = rate !== null ? rate * qtl : null;
            return (
              <div className="entry-row entry-row-pricing" key={d.id}>
                <div className="entry-info">
                  <div className="strong">{t.balesSubTab}: {d.buyer}</div>
                  <div className="muted">{d.totalBales} {t.balesSelectedCount} · {d.totalWeight.toFixed(1)} kg ({qtl.toFixed(2)} {t.qtl})</div>
                  <div className="muted entry-date">{d.date}</div>
                  <div className="subtab-row" style={{ marginTop: 6, marginBottom: 0 }}>
                    <button type="button" className={"subtab" + (row.mode === "quintal" ? " subtab-active" : "")} onClick={() => setBaleRowMode(d.id, "quintal")}>{t.rateModeQuintal}</button>
                    <button type="button" className={"subtab" + (row.mode === "candy" ? " subtab-active" : "")} onClick={() => setBaleRowMode(d.id, "candy")}>{t.rateModeCandy}</button>
                  </div>
                </div>
                <div className="pricing-input-col">
                  <input className="text-input small" type="number" placeholder={row.mode === "candy" ? t.candyRatePh : t.ratePh} value={row.value} onChange={(e) => setBaleRowValue(d.id, e.target.value)} />
                  {row.mode === "candy" && rate !== null && <div className="tiny-note" style={{ margin: "4px 0 0" }}>{t.equivPerQtl}: ₹{rate.toFixed(2)}{t.perQtl}</div>}
                  {amount !== null && !isNaN(amount) && <div className="live-total">{t.totalPreviewLabel} ₹{amount.toFixed(0)}</div>}
                </div>
                <button className="secondary-btn" disabled={!row.value || savingId === d.id} onClick={() => saveBale(d.id)}>
                  {savingId === d.id ? t.saving : errorId === d.id ? t.tryAgain : t.setRateBtn}
                </button>
              </div>
            );
          })}
        </div>
      )}

      {(pricedCottonseed.length > 0 || pricedBales.length > 0) && (
        <>
          <h3 className="section-title small-title">{t.pricedInvoicesTitle}</h3>
          <div className="row-list">
            {pricedCottonseed.map((d) => (
              <div className="entry-row" key={d.id}>
                <div className="entry-info">
                  <div className="strong">{t.cottonseedSubTab}: {d.lorryNumber}</div>
                  <div className="muted">{d.totalWeight.toFixed(2)} {t.qtl} × ₹{d.rate}{t.perQtl}</div>
                  <div className="muted entry-date">{d.date}</div>
                </div>
                <div className="mono net-preview">₹{(d.rate * d.totalWeight).toFixed(0)}</div>
                <button className="secondary-btn" onClick={() => setInvoice({ kind: "cottonseed", record: d })}>{t.viewInvoice}</button>
              </div>
            ))}
            {pricedBales.map((d) => {
              const qtl = d.totalWeight / 100;
              return (
                <div className="entry-row" key={d.id}>
                  <div className="entry-info">
                    <div className="strong">{t.balesSubTab}: {d.buyer}</div>
                    <div className="muted">
                      {d.totalBales} {t.balesSelectedCount} · {d.totalWeight.toFixed(1)} kg ({qtl.toFixed(2)} {t.qtl}) × ₹{d.rate.toFixed(2)}{t.perQtl}
                      {d.candyRate ? ` (${t.rateModeCandy}: ₹${d.candyRate})` : ""}
                    </div>
                    <div className="muted entry-date">{d.date}</div>
                  </div>
                  <div className="mono net-preview">₹{(d.rate * qtl).toFixed(0)}</div>
                  <button className="secondary-btn" onClick={() => setInvoice({ kind: "bale", record: d })}>{t.viewInvoice}</button>
                </div>
              );
            })}
          </div>
        </>
      )}

      <h3 className="section-title small-title">{t.heapPnlTitle}</h3>
      {closedHeaps.length === 0 ? (
        <div className="empty-state">{t.noHeapsForPnl}</div>
      ) : (
        <div className="table-scroll"><table className="ledger-table">
          <thead>
            <tr>
              <th>{t.thHeapCol}</th>
              <th className="num">{t.thKapasCost}</th>
              <th className="num">{t.thCottonseedRev}</th>
              <th className="num">{t.thBaleRev}</th>
              <th className="num">{t.thTotalRev}</th>
              <th className="num">{t.thProfitLoss}</th>
              <th className="num">{t.thShortage}</th>
            </tr>
          </thead>
          <tbody>
            {closedHeaps.map((h) => {
              const { cost, partial } = heapKapasCost(h.id, lorries);
              const cs = heapCottonseedRevenue(h.id, cottonseedDispatches);
              const bl = heapBaleRevenue(h.id, bales, baleDispatches);
              const totalRev = cs.revenue + bl.revenue;
              const pl = totalRev - cost;
              const kapasQtl = heapStats(h.id, lorries).totalWeight;
              const outputQtl = cs.weightQtl + bl.weightQtl;
              const shortagePct = kapasQtl > 0 ? ((kapasQtl - outputQtl) / kapasQtl) * 100 : null;
              return (
                <tr key={h.id}>
                  <td className="mono">#{h.heapNumber}{partial ? "*" : ""}</td>
                  <td className="num mono">{cost.toFixed(0)}</td>
                  <td className="num mono">{cs.revenue.toFixed(0)}</td>
                  <td className="num mono">{bl.revenue.toFixed(0)}</td>
                  <td className="num mono">{totalRev.toFixed(0)}</td>
                  <td className="num mono" style={{ color: pl >= 0 ? "#3E6B4F" : "#9C3B34", fontWeight: 700 }}>{pl.toFixed(0)}</td>
                  <td className="num mono" style={shortagePct !== null && shortagePct < 0 ? { color: "#9C3B34", fontWeight: 700 } : undefined}>
                    {shortagePct !== null ? shortagePct.toFixed(1) + "%" : "—"}
                    {shortagePct !== null && shortagePct < 0 && <div className="tiny-note" style={{ margin: "2px 0 0", color: "#9C3B34" }}>{t.shortageImpossibleNote}</div>}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table></div>
      )}
      {closedHeaps.some((h) => heapKapasCost(h.id, lorries).partial) && <p className="tiny-note">{t.partialCostNote}</p>}

      {invoice && <DispatchInvoiceModal t={t} kind={invoice.kind} record={invoice.record} onClose={() => setInvoice(null)} />}
    </div>
  );
}

function DispatchInvoiceModal({ t, kind, record, onClose }) {
  useEffect(() => {
    document.body.classList.add("print-only-modal");
    return () => document.body.classList.remove("print-only-modal");
  }, []);
  const isCottonseed = kind === "cottonseed";
  const qtl = isCottonseed ? record.totalWeight : record.totalWeight / 100;
  const amount = (record.rate || 0) * qtl;
  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-card" onClick={(e) => e.stopPropagation()}>
        <div className="slip-header">
          <div className="stamp">{isCottonseed ? t.cottonseedInvoiceTitle : t.baleInvoiceTitle}</div>
          <div className="mono">{record.date}</div>
        </div>
        <div className="slip-line"><span>{isCottonseed ? t.lorryLabel : t.buyerLabel}</span><span>{isCottonseed ? record.lorryNumber : record.buyer}</span></div>
        {!isCottonseed && <div className="slip-line"><span>{t.totalBalesLabel}</span><span className="mono">{record.totalBales}</span></div>}
        {!isCottonseed && <div className="slip-line"><span>{t.weightLabel} (kg)</span><span className="mono">{record.totalWeight.toFixed(1)} kg</span></div>}
        <div className="slip-line"><span>{t.weightLabel} ({t.qtl})</span><span className="mono">{qtl.toFixed(2)} {t.qtl}</span></div>
        {!isCottonseed && record.candyRate && (
          <div className="slip-line muted-line"><span>{t.rateModeCandy}</span><span className="mono">₹{record.candyRate} × 0.2812</span></div>
        )}
        <div className="slip-line"><span>{t.rateLabelSlip} (₹{t.perQtl})</span><span className="mono">₹{record.rate.toFixed(2)}{t.perQtl}</span></div>
        <div className="slip-divider" />
        <div className="slip-line slip-total"><span>{t.grossLabel}</span><span className="mono">₹{amount.toFixed(2)}</span></div>
        <p className="tiny-note">{t.invoiceReviewNote}</p>
        <div className="modal-actions">
          <button className="link-btn-dark no-print" onClick={onClose}>{t.close}</button>
          <button className="secondary-btn no-print" onClick={() => window.print()}>{t.printBtn}</button>
        </div>
      </div>
    </div>
  );
}

// ---------- Raw data (read-only) ----------
function RawSection({ t, title, count, storageKey, rawKey, setRawKey, raw, children }) {
  const showRaw = rawKey === storageKey;
  return (
    <div className="heap-card" style={{ marginBottom: 14 }}>
      <div className="heap-card-top">
        <div className="heap-card-num">{title} <span className="muted">({count})</span></div>
        <button className="link-btn-dark" onClick={() => setRawKey(showRaw ? null : storageKey)}>
          {showRaw ? t.hideRawJson : t.viewRawJson}
        </button>
      </div>
      {showRaw ? <pre className="raw-json">{JSON.stringify(raw, null, 2)}</pre> : children}
    </div>
  );
}

function RawDataView({ t, lorries, heaps, bales, settings, cottonseedDispatches, baleDispatches }) {
  const [rawKey, setRawKey] = useState(null);
  const heapNum = (id) => (heaps.find((h) => h.id === id)?.heapNumber ? "#" + heaps.find((h) => h.id === id).heapNumber : "—");

  return (
    <div>
      <h2 className="section-title">{t.rawDataSectionTitle}</h2>
      <p className="sub">{t.rawDataSectionSub}</p>

      <RawSection t={t} title={t.settingsTab} count={settings.hammaliRate !== undefined ? 1 : 0} storageKey="settings" rawKey={rawKey} setRawKey={setRawKey} raw={settings}>
        <div className="mono">₹{settings.hammaliRate ?? "—"} {t.perQtl}</div>
      </RawSection>

      <RawSection t={t} title={t.heapsTab} count={heaps.length} storageKey="heaps" rawKey={rawKey} setRawKey={setRawKey} raw={heaps}>
        {heaps.length === 0 ? <div className="empty-state">{t.noRecordsYet}</div> : (
          <div className="table-scroll"><table className="ledger-table heap-mini-table">
            <thead><tr><th>#</th><th>{t.thStatus}</th></tr></thead>
            <tbody>{heaps.map((h) => (<tr key={h.id}><td className="mono">#{h.heapNumber}</td><td><span className="badge" style={{ background: h.status === "open" ? "#6D8E4E" : h.status === "pending" ? "#C99A3C" : "#64748B" }}>{h.status}</span></td></tr>))}</tbody>
          </table></div>
        )}
      </RawSection>

      <RawSection t={t} title={t.ledgerTab} count={lorries.length} storageKey="lorries" rawKey={rawKey} setRawKey={setRawKey} raw={lorries}>
        {lorries.length === 0 ? <div className="empty-state">{t.noRecordsYet}</div> : (
          <div className="table-scroll"><table className="ledger-table heap-mini-table">
            <thead><tr><th>{t.thRst}</th><th className="num">{t.thWeight}</th><th>{t.thHeap}</th><th>{t.thStatus}</th></tr></thead>
            <tbody>{lorries.map((l) => (<tr key={l.id}><td className="mono">{l.rst || "—"}</td><td className="num mono">{l.weight}</td><td className="mono">{heapNum(l.heapId)}</td><td>{l.status}</td></tr>))}</tbody>
          </table></div>
        )}
      </RawSection>

      <RawSection t={t} title={t.baleTab} count={bales.length} storageKey="bales" rawKey={rawKey} setRawKey={setRawKey} raw={bales}>
        {bales.length === 0 ? <div className="empty-state">{t.noRecordsYet}</div> : (
          <div className="table-scroll"><table className="ledger-table heap-mini-table">
            <thead><tr><th>{t.heapNumberLabel}</th><th>{t.baleNumberLabel}</th><th className="num">{t.baleWeightLabel}</th><th>Dispatched</th><th>{t.thTime}</th></tr></thead>
            <tbody>{bales.map((b) => (<tr key={b.id}><td className="mono">{heapNum(b.heapId)}</td><td className="mono">#{b.baleNumber}</td><td className="num mono">{b.weight}</td><td>{b.dispatched ? "yes" : "no"}</td><td className="muted">{b.date} · {b.time}</td></tr>))}</tbody>
          </table></div>
        )}
      </RawSection>

      <RawSection t={t} title={t.cottonseedSubTab} count={cottonseedDispatches.length} storageKey="cottonseedDispatches" rawKey={rawKey} setRawKey={setRawKey} raw={cottonseedDispatches}>
        {cottonseedDispatches.length === 0 ? <div className="empty-state">{t.noRecordsYet}</div> : (
          <div className="table-scroll"><table className="ledger-table heap-mini-table">
            <thead><tr><th>{t.lorryLabel}</th><th className="num">Wt (Qtl)</th><th className="num">₹</th></tr></thead>
            <tbody>{cottonseedDispatches.map((d) => (<tr key={d.id}><td>{d.lorryNumber}</td><td className="num mono">{d.totalWeight}</td><td className="num mono">{d.rate ?? "—"}</td></tr>))}</tbody>
          </table></div>
        )}
      </RawSection>

      <RawSection t={t} title={t.balesSubTab} count={baleDispatches.length} storageKey="baleDispatches" rawKey={rawKey} setRawKey={setRawKey} raw={baleDispatches}>
        {baleDispatches.length === 0 ? <div className="empty-state">{t.noRecordsYet}</div> : (
          <div className="table-scroll"><table className="ledger-table heap-mini-table">
            <thead><tr><th>{t.buyerLabel}</th><th className="num">Bales</th><th className="num">₹</th></tr></thead>
            <tbody>{baleDispatches.map((d) => (<tr key={d.id}><td>{d.buyer}</td><td className="num mono">{d.totalBales}</td><td className="num mono">{d.rate ?? "—"}</td></tr>))}</tbody>
          </table></div>
        )}
      </RawSection>
    </div>
  );
}

// ---------- Settings ----------
function SettingsView({ t, settings, onSave, users, session, onReset, onDeleteUser, onRegister }) {
  const [value, setValue] = useState(settings.hammaliRate || "");
  const [saved, setSaved] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(false);

  useEffect(() => setValue(settings.hammaliRate || ""), [settings.hammaliRate]);

  async function submit(e) {
    e.preventDefault();
    if (value === "") return;
    setSaving(true);
    setError(false);
    try {
      const result = await onSave(value);
      if (result && result.error) {
        setError(true);
        return;
      }
      setSaved(true);
      setTimeout(() => setSaved(false), 2500);
    } catch (e) {
      console.error("submit failed", e);
      setError(true);
    } finally {
      setSaving(false);
    }
  }

  return (
    <div>
      <div className="form-card">
        <h2>{t.settingsTitle}</h2>
        <p className="sub">{t.settingsSub}</p>
        <div className="current-rate-note">{t.currentRate} <span className="mono strong">₹{settings.hammaliRate || 0}{t.perQtl}</span></div>
        <form onSubmit={submit}>
          <label className="field-label">{t.hammaliRateLabel}</label>
          <input className="text-input" type="number" step="0.5" value={value} onChange={(e) => setValue(e.target.value)} placeholder={t.hammaliRatePh} />
          <p className="tiny-note">{t.weighingChargeFixedNote}</p>
          <button className="primary-btn" type="submit" disabled={saving}>{saving ? t.saving : error ? t.tryAgain : t.saveSettings}</button>
        </form>
        {error && (
          <div className="slip-note" style={{ background: "#FBEAEA", color: "#9C3B34", borderColor: "#E3B4B0" }}>
            {t.saveError}
          </div>
        )}
        {saved && !error && <div className="slip-note">{t.settingsSaved}</div>}
      </div>

      <ManageUsersSection t={t} users={users} session={session} onDeleteUser={onDeleteUser} onRegister={onRegister} />
      <DangerZoneSection t={t} session={session} users={users} onReset={onReset} />
    </div>
  );
}

function ManageUsersSection({ t, users, session, onDeleteUser, onRegister }) {
  const [confirmId, setConfirmId] = useState(null);
  const [deletingId, setDeletingId] = useState(null);
  const [errorId, setErrorId] = useState(null);
  const [showRegister, setShowRegister] = useState(false);
  const [justRegistered, setJustRegistered] = useState(null);

  async function doDelete(id) {
    setDeletingId(id);
    setErrorId(null);
    try {
      const result = await onDeleteUser(id);
      if (result && result.error) {
        setErrorId(id);
        return;
      }
      setConfirmId(null);
    } catch (e) {
      console.error("doDelete failed", e);
      setErrorId(id);
    } finally {
      setDeletingId(null);
    }
  }

  return (
    <div className="form-card" style={{ marginTop: 20 }}>
      <h2>{t.manageUsersTitle}</h2>
      <p className="sub">{t.manageUsersSub}</p>
      {users.length === 0 ? (
        <div className="empty-state">{t.noRecordsYet}</div>
      ) : (
        <div className="row-list">
          {users.map((u) => {
            const isSelf = u.id === session.userId;
            const confirming = confirmId === u.id;
            return (
              <div className="entry-row" key={u.id}>
                <Avatar user={u} size={40} />
                <div className="entry-info">
                  <div className="strong">{u.name}</div>
                  <div className="muted">{roleLabels(t, u)}{isSelf ? ` · ${t.thatsYouNote}` : ""}</div>
                </div>
                {!confirming ? (
                  <button className="link-btn-dark" disabled={isSelf} onClick={() => setConfirmId(u.id)}>{t.deleteUserBtn}</button>
                ) : (
                  <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
                    <button className="link-btn-dark" onClick={() => setConfirmId(null)}>{t.cancelBtn}</button>
                    <button className="secondary-btn" style={{ background: "#9C3B34" }} disabled={deletingId === u.id} onClick={() => doDelete(u.id)}>
                      {deletingId === u.id ? t.saving : errorId === u.id ? t.tryAgain : t.confirmBtn}
                    </button>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {!showRegister ? (
        <button className="secondary-btn" style={{ marginTop: 14 }} onClick={() => { setShowRegister(true); setJustRegistered(null); }}>
          {t.registerNewPerson}
        </button>
      ) : (
        <div style={{ marginTop: 16, paddingTop: 16, borderTop: "1px dashed #C3D4E6" }}>
          <RegisterForm
            t={t}
            onRegister={onRegister}
            onCancel={() => setShowRegister(false)}
            onDone={(user) => { setJustRegistered(user); setShowRegister(false); }}
          />
        </div>
      )}
      {justRegistered && (
        <div className="slip-note">
          {t.personRegisteredNote} <span className="strong">{justRegistered.name}</span> ({roleLabels(t, justRegistered)})
        </div>
      )}
    </div>
  );
}

function DangerZoneSection({ t, session, users, onReset }) {
  const [confirming, setConfirming] = useState(false);
  const [input, setInput] = useState("");
  const [resetting, setResetting] = useState(false);
  const [error, setError] = useState(null);
  const [done, setDone] = useState(false);

  const me = users.find((u) => u.id === session.userId);
  const hasPin = !!(me && me.pin);

  async function submit(e) {
    e.preventDefault();
    if (!input.trim()) return;
    setResetting(true);
    setError(null);
    try {
      const result = await onReset(input.trim());
      if (result && result.error) {
        setError(result.reason || "generic");
        return;
      }
      setDone(true);
      setInput("");
      setConfirming(false);
    } catch (e) {
      console.error("reset submit failed", e);
      setError("generic");
    } finally {
      setResetting(false);
    }
  }

  return (
    <div className="form-card danger-zone" style={{ marginTop: 20 }}>
      <h2>{t.dangerZoneTitle}</h2>
      <p className="sub">{t.dangerZoneSub}</p>
      {!confirming ? (
        <button className="secondary-btn" style={{ background: "#9C3B34" }} onClick={() => { setConfirming(true); setDone(false); setError(null); }}>
          {t.resetAllBtn}
        </button>
      ) : (
        <form onSubmit={submit}>
          <p className="tiny-note" style={{ color: "#9C3B34" }}>{t.resetAllWarning}</p>
          <label className="field-label">{hasPin ? t.enterYourPinLabel : t.typeResetLabel}</label>
          <input
            className="text-input"
            type={hasPin ? "password" : "text"}
            inputMode={hasPin ? "numeric" : "text"}
            maxLength={hasPin ? 4 : 10}
            value={input}
            onChange={(e) => setInput(hasPin ? e.target.value.replace(/\D/g, "") : e.target.value.toUpperCase())}
            placeholder={hasPin ? t.pinPh : "RESET"}
          />
          {error && (
            <div className="slip-note" style={{ background: "#FBEAEA", color: "#9C3B34", borderColor: "#E3B4B0" }}>
              {error === "pin" ? t.resetWrongPin : error === "confirm" ? t.resetWrongConfirm : t.saveError}
            </div>
          )}
          <div className="modal-actions" style={{ marginTop: 16 }}>
            <button type="button" className="link-btn-dark" onClick={() => setConfirming(false)}>{t.cancelBtn}</button>
            <button className="primary-btn" style={{ marginTop: 0, width: "auto", padding: "10px 20px", background: "#9C3B34" }} type="submit" disabled={resetting}>
              {resetting ? t.saving : t.confirmResetBtn}
            </button>
          </div>
        </form>
      )}
      {done && <div className="slip-note">{t.resetDoneNote}</div>}
    </div>
  );
}

